//
// Semantic runtime resolution: `memwarden up` installs transformers.js under
// <dataDir>/runtime and the embedding loader must find it there without the
// bare specifier resolving. Uses a fake package fixture — the mechanism under
// test is resolution + entry import, not transformers itself.

import { describe, expect, it, beforeAll, afterAll } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import {
  resolveTransformersEntry,
  semanticRuntimeRoot,
} from "../src/embedding/runtime.js";

let root: string;

beforeAll(() => {
  root = mkdtempSync(join(tmpdir(), "mw-runtime-"));
  const pkgDir = join(root, "node_modules", "@huggingface", "transformers");
  mkdirSync(join(pkgDir, "dist"), { recursive: true });
  writeFileSync(
    join(pkgDir, "package.json"),
    JSON.stringify({
      name: "@huggingface/transformers",
      version: "3.8.1",
      type: "module",
      exports: {
        node: { import: { default: "./dist/fake.node.mjs" } },
        default: { default: "./dist/fake.web.js" },
      },
    }),
  );
  writeFileSync(
    join(pkgDir, "dist", "fake.node.mjs"),
    "export function pipeline() { return async () => ({ tolist: () => [[0.1]] }); }\n",
  );
});

afterAll(() => {
  rmSync(root, { recursive: true, force: true });
});

describe("semantic runtime resolution", () => {
  it("resolves the node ESM entry from a runtime root", () => {
    const entry = resolveTransformersEntry(root);
    expect(entry).toBeTruthy();
    expect(entry).toContain("fake.node.mjs");
  });

  it("returns null when the package is absent", () => {
    expect(resolveTransformersEntry(join(root, "nope"))).toBeNull();
  });

  it("the resolved entry imports and exposes pipeline()", async () => {
    const entry = resolveTransformersEntry(root)!;
    const mod = (await import(pathToFileURL(entry).href)) as {
      pipeline?: unknown;
    };
    expect(typeof mod.pipeline).toBe("function");
  });

  it("semanticRuntimeRoot honors an explicit dataDir over env", () => {
    expect(semanticRuntimeRoot("/x/data")).toBe(join("/x/data", "runtime"));
  });
});

//
// Canon's core/API boundary: exact project-scoped Memory inventory and a
// dedicated import that can only create hash-verified provenance after checking
// this checkout. These tests intentionally bypass semantic search/observe.
//

import { once } from "node:events";
import { mkdirSync, mkdtempSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import type { AddressInfo } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  __resetKernelSingleton,
  registerWorker,
  startHttpServer,
  type Kernel,
  type RunningHttpServer,
} from "../src/kernel/index.js";
import {
  getSearchIndex,
  registerCoreFunctions,
} from "../src/functions/index.js";
import { projectKey } from "../src/functions/git-identity.js";
import {
  classifyProvenance,
  hashFileCommitments,
} from "../src/functions/verify.js";
import type { CanonRecord, Memory } from "../src/functions/types.js";
import { StateKV } from "../src/state/kv.js";
import { KV } from "../src/state/schema.js";
import { StoreMemory } from "../src/state/store-memory.js";
import { registerApiTriggers } from "../src/triggers/api.js";

let sdk: Kernel;
let kv: StateKV;
let http: RunningHttpServer;
let base: string;
let temp: string;
let repoA: string;
let repoB: string;

function makeRepo(name: string, remote: string): string {
  const root = join(temp, name);
  mkdirSync(join(root, ".git"), { recursive: true });
  writeFileSync(
    join(root, ".git", "config"),
    `[remote "origin"]\n\turl = ${remote}\n`,
    "utf8",
  );
  return realpathSync(root);
}

function memory(id: string, root: string, content = id): Memory {
  const now = new Date().toISOString();
  return {
    id,
    createdAt: now,
    updatedAt: now,
    type: "architecture",
    title: `Title ${id}`,
    content,
    concepts: [id],
    files: ["src/source.ts"],
    sessionIds: [],
    strength: 5,
    version: 1,
    isLatest: true,
    project: root,
    projectKey: projectKey(root),
    provenance: {
      cwd: root,
      files: ["src/source.ts"],
      fileHashes: { "src/source.ts": "a".repeat(64) },
    },
  };
}

function canonRecord(root: string, id = "mem_import"): CanonRecord {
  const source = "export const answer = 42;\n";
  mkdirSync(join(root, "src"), { recursive: true });
  writeFileSync(join(root, "src/source.ts"), source, "utf8");
  const commitments = hashFileCommitments(["src/source.ts"], root);
  return {
    format: 1,
    id,
    type: "architecture",
    projectKey: projectKey(root),
    title: "The exact imported title",
    content: "The exact imported content says answer is 42.",
    concepts: ["answer", "canon"],
    files: ["src/source.ts"],
    ...commitments,
    capturedBy: { host: "claude-code", agentId: "agent-7" },
    promotedAt: "2025-01-02T03:04:05.000Z",
    reanchoredBy: "alice",
    reanchoredAt: "2025-02-03T04:05:06.000Z",
  };
}

async function post(
  path: string,
  body: unknown,
  authenticated = true,
): Promise<Response> {
  return fetch(`${base}${path}`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      ...(authenticated ? { authorization: "Bearer <REDACTED>" } : {}),
    },
    body: JSON.stringify(body),
  });
}

beforeEach(async () => {
  __resetKernelSingleton();
  getSearchIndex().clear();
  temp = realpathSync(mkdtempSync(join(tmpdir(), "memwarden-canon-api-")));
  repoA = makeRepo("a", "git@github.com:acme/project-a.git");
  repoB = makeRepo("b", "git@github.com:acme/project-b.git");

  sdk = registerWorker("in-process", { workerName: "memwarden-canon-api" }, {
    store: new StoreMemory(),
  });
  kv = new StateKV(sdk);
  registerCoreFunctions(sdk, kv);
  registerApiTriggers(sdk, "canon-test-secret");
  http = startHttpServer(sdk, { port: 0 });
  await once(http.server, "listening");
  base = `http://127.0.0.1:${(http.server.address() as AddressInfo).port}/memwarden`;
});

afterEach(async () => {
  await http.close().catch(() => undefined);
  await sdk.shutdown();
  rmSync(temp, { recursive: true, force: true });
  __resetKernelSingleton();
});

describe("Canon core/API boundary", () => {
  it("pages real Memory rows for one exact project identity, never search results", async () => {
    await kv.set(KV.memories, "mem_a1", memory("mem_a1", repoA));
    await kv.set(KV.memories, "mem_a2", memory("mem_a2", repoA));
    await kv.set(KV.memories, "mem_b", memory("mem_b", repoB));

    const first = await post("/canon/export", { root: repoA, limit: 1 });
    expect(first.status).toBe(200);
    const page1 = (await first.json()) as {
      project: { root: string; key: string };
      memories: Memory[];
      nextCursor?: string;
    };
    expect(page1.project).toEqual({ root: repoA, key: projectKey(repoA) });
    expect(page1.memories.map((m) => m.id)).toEqual(["mem_a1"]);
    expect(page1.memories[0]!.title).toBe("Title mem_a1");
    expect(page1.nextCursor).toBe("mem_a1");

    const second = await post("/canon/export", {
      root: repoA,
      limit: 1,
      cursor: page1.nextCursor,
    });
    const page2 = (await second.json()) as { memories: Memory[]; nextCursor?: string };
    expect(page2.memories.map((m) => m.id)).toEqual(["mem_a2"]);
    expect(page2.nextCursor).toBeUndefined();
    expect(page2.memories.some((m) => m.id === "mem_b")).toBe(false);
  });

  it("imports exact content/evidence/project/attestation only after local hash matching", async () => {
    const record = canonRecord(repoA);
    const response = await post("/canon/import", { root: repoA, record });
    expect(response.status).toBe(201);
    expect(await response.json()).toMatchObject({
      ok: true,
      imported: true,
      id: record.id,
      projectKey: record.projectKey,
      verdict: "verified",
    });

    const stored = await kv.get<Memory>(KV.memories, record.id);
    expect(stored).toMatchObject({
      id: record.id,
      type: record.type,
      title: record.title,
      content: record.content,
      concepts: record.concepts,
      files: record.files,
      projectPath: repoA,
      projectKey: record.projectKey,
      captureCwd: repoA,
      agentId: "agent-7",
      provenance: {
        cwd: repoA,
        files: record.files,
        fileHashes: record.fileHashes,
        fileHashesNormalized: record.fileHashesNormalized,
        agent: "claude-code",
        canon: {
          format: 1,
          recordId: record.id,
          projectKey: record.projectKey,
          promotedAt: record.promotedAt,
          capturedBy: record.capturedBy,
          reanchoredBy: record.reanchoredBy,
          reanchoredAt: record.reanchoredAt,
        },
      },
    });
    expect(stored?.project).toBeUndefined();
  });

  it("imports an LF Canon record into a CRLF checkout as cosmetic/current", async () => {
    const record = canonRecord(repoA, "mem_cosmetic");
    writeFileSync(
      join(repoA, "src/source.ts"),
      "export const answer = 42;\r\n",
      "utf8",
    );

    const response = await post("/canon/import", { root: repoA, record });
    expect(response.status).toBe(201);
    expect(await response.json()).toMatchObject({
      ok: true,
      id: record.id,
      verdict: "cosmetic",
    });
    const stored = await kv.get<Memory>(KV.memories, record.id);
    expect(stored?.provenance?.fileHashes).toEqual(record.fileHashes);
    expect(stored?.provenance?.fileHashesNormalized).toEqual(
      record.fileHashesNormalized,
    );
    expect(classifyProvenance(stored?.provenance, repoA).status).toBe(
      "cosmetic",
    );
  });

  it("rejects caller-claimed verification when hashes do not match, even via the core id", async () => {
    const record = canonRecord(repoA, "mem_forged");
    const forged = {
      ...record,
      fileHashes: { "src/source.ts": "b".repeat(64) },
      fileHashesNormalized: { "src/source.ts": "c".repeat(64) },
      verified: true,
      verdict: "verified",
    };

    const response = await post("/canon/import", { root: repoA, record: forged });
    expect(response.status).toBe(409);
    expect(await response.json()).toMatchObject({
      ok: false,
      code: "hash_mismatch",
    });
    expect(await kv.get(KV.memories, record.id)).toBeNull();

    const direct = await sdk.trigger<
      { root: string; record: unknown },
      { ok: boolean; code?: string }
    >({
      function_id: "mem::canon-import",
      payload: { root: repoA, record: forged },
    });
    expect(direct).toMatchObject({ ok: false, code: "hash_mismatch" });
    expect(await kv.get(KV.memories, record.id)).toBeNull();

    const inconsistent = {
      ...record,
      id: "mem_inconsistent_normalized",
      fileHashesNormalized: { "src/source.ts": "d".repeat(64) },
    };
    const inconsistentResponse = await post("/canon/import", {
      root: repoA,
      record: inconsistent,
    });
    expect(inconsistentResponse.status).toBe(409);
    expect(await inconsistentResponse.json()).toMatchObject({
      ok: false,
      code: "hash_mismatch",
    });
  });

  it("rejects a valid record from a different project identity", async () => {
    const record = canonRecord(repoA, "mem_wrong_project");
    const response = await post("/canon/import", { root: repoB, record });
    expect(response.status).toBe(409);
    expect(await response.json()).toMatchObject({
      ok: false,
      code: "project_mismatch",
    });
    expect(await kv.get(KV.memories, record.id)).toBeNull();
  });

  it("keeps both Canon routes behind the existing bearer-secret gate", async () => {
    expect((await post("/canon/export", { root: repoA }, false)).status).toBe(401);
    expect(
      (await post("/canon/import", { root: repoA, record: canonRecord(repoA) }, false))
        .status,
    ).toBe(401);
  });
});

//
// Embedding provider selection. Construction must be cheap and model-free
// (the heavy load is lazy), so these tests never touch the network — they
// assert the factory wiring and the TurboQuant-follows-embeddings default,
// not actual inference.

import { afterEach, describe, expect, it, vi } from "vitest";
import {
  createEmbeddingProvider,
  getEmbeddingProviderName,
  getEmbeddingModel,
  LocalEmbeddingProvider,
} from "../src/embedding/index.js";
import { isQuantizedVectorEnabled } from "../src/functions/config.js";

const embeddingMocks = vi.hoisted(() => ({
  outputDispose: vi.fn(),
  pipelineDispose: vi.fn(async () => undefined),
}));

vi.mock("../src/embedding/runtime.js", () => ({
  importTransformers: async () => ({
    pipeline: async () =>
      Object.assign(
        async (input: string | string[]) => ({
          tolist: () =>
            (Array.isArray(input) ? input : [input]).map(() => [0.5, -0.5]),
          dispose: embeddingMocks.outputDispose,
        }),
        { dispose: embeddingMocks.pipelineDispose },
      ),
  }),
}));

afterEach(() => {
  delete process.env.MEMWARDEN_EMBEDDING_PROVIDER;
  delete process.env.MEMWARDEN_EMBEDDING_MODEL;
  delete process.env.MEMWARDEN_QUANT_VECTOR;
  vi.clearAllMocks();
});

describe("embedding provider factory", () => {
  it("defaults to a local MiniLM provider (384d), no model load on construct", () => {
    const p = createEmbeddingProvider();
    expect(p).toBeInstanceOf(LocalEmbeddingProvider);
    expect(p!.name).toBe("local:Xenova/all-MiniLM-L6-v2");
    expect(p!.dimensions).toBe(384);
  });

  it("returns null in BM25-only mode", () => {
    process.env.MEMWARDEN_EMBEDDING_PROVIDER = "none";
    expect(getEmbeddingProviderName()).toBe("none");
    expect(createEmbeddingProvider()).toBeNull();
  });

  it("honors a custom model name", () => {
    process.env.MEMWARDEN_EMBEDDING_MODEL = "Xenova/bge-small-en-v1.5";
    expect(getEmbeddingModel()).toBe("Xenova/bge-small-en-v1.5");
    const p = createEmbeddingProvider();
    expect(p!.dimensions).toBe(384);
    expect(p!.name).toContain("bge-small");
  });

  it("disposes inference outputs and the native model session before shutdown", async () => {
    const p = new LocalEmbeddingProvider();
    await p.embed("one");
    await p.embedBatch(["two", "three"]);
    expect(embeddingMocks.outputDispose).toHaveBeenCalledTimes(2);

    await p.dispose();
    expect(embeddingMocks.pipelineDispose).toHaveBeenCalledTimes(1);
    await expect(p.embed("after shutdown")).rejects.toThrow("shutting down");
  });
});

describe("TurboQuant follows the embedding provider", () => {
  it("is on by default when embeddings are active", () => {
    expect(isQuantizedVectorEnabled()).toBe(true); // provider defaults to local
  });

  it("is off when embeddings are disabled", () => {
    process.env.MEMWARDEN_EMBEDDING_PROVIDER = "none";
    expect(isQuantizedVectorEnabled()).toBe(false);
  });

  it("explicit MEMWARDEN_QUANT_VECTOR overrides either way", () => {
    process.env.MEMWARDEN_EMBEDDING_PROVIDER = "none";
    process.env.MEMWARDEN_QUANT_VECTOR = "true";
    expect(isQuantizedVectorEnabled()).toBe(true);
    process.env.MEMWARDEN_EMBEDDING_PROVIDER = "local";
    process.env.MEMWARDEN_QUANT_VECTOR = "false";
    expect(isQuantizedVectorEnabled()).toBe(false);
  });
});

//
// Project identity: normalized git remote / main-repo-root keys that survive
// worktrees and moved checkouts. All filesystem cases run against synthetic
// .git layouts in a temp dir (no `git` binary, matching the implementation).

import { afterEach, describe, expect, it } from "vitest";
import { mkdtempSync, rmSync, writeFileSync, mkdirSync, realpathSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  normalizeGitRemote,
  remoteUrlFromConfig,
  gitProjectKey,
  projectKey,
  __resetGitIdentityCache,
} from "../src/functions/git-identity.js";

const dirs: string[] = [];
function tempDir(): string {
  // realpath so macOS /tmp -> /private/tmp symlinks don't skew comparisons.
  const d = realpathSync(mkdtempSync(join(tmpdir(), "memwarden-git-id-")));
  dirs.push(d);
  return d;
}
afterEach(() => {
  __resetGitIdentityCache();
  for (const d of dirs.splice(0)) rmSync(d, { recursive: true, force: true });
});

describe("normalizeGitRemote", () => {
  it("normalizes every spelling of the same repo to one key", () => {
    const expected = "github.com/acme/rocket";
    for (const url of [
      "git@github.com:acme/rocket.git",
      "https://github.com/acme/rocket.git",
      "https://github.com/acme/rocket",
      "ssh://git@github.com/acme/rocket.git",
      "https://user:token@github.com/acme/rocket.git",
      "ssh://git@github.com:22/acme/rocket.git",
      "git@GitHub.com:Acme/Rocket.git",
    ]) {
      expect(normalizeGitRemote(url), url).toBe(expected);
    }
  });

  it("keeps nested groups and self-hosted hosts", () => {
    expect(normalizeGitRemote("git@gitlab.example.io:group/sub/repo.git")).toBe(
      "gitlab.example.io/group/sub/repo",
    );
  });

  it("returns null for file/local/unrecognized remotes", () => {
    expect(normalizeGitRemote("/abs/local/repo.git")).toBeNull();
    expect(normalizeGitRemote("file:///abs/local/repo.git")).toBeNull();
    expect(normalizeGitRemote("../relative/repo")).toBeNull();
    expect(normalizeGitRemote("")).toBeNull();
  });
});

describe("remoteUrlFromConfig", () => {
  it("prefers origin over other remotes regardless of order", () => {
    const config = [
      "[core]",
      "\trepositoryformatversion = 0",
      '[remote "upstream"]',
      "\turl = git@github.com:acme/upstream.git",
      '[remote "origin"]',
      "\turl = git@github.com:acme/rocket.git",
      "\tfetch = +refs/heads/*:refs/remotes/origin/*",
    ].join("\n");
    expect(remoteUrlFromConfig(config)).toBe("git@github.com:acme/rocket.git");
  });

  it("falls back to the first remote when origin is absent; null when none", () => {
    expect(
      remoteUrlFromConfig('[remote "fork"]\n\turl = git@h.io:a/b.git\n'),
    ).toBe("git@h.io:a/b.git");
    expect(remoteUrlFromConfig("[core]\n\tbare = false\n")).toBeNull();
  });
});

// Build a synthetic main repo (+ optional linked worktree) on disk.
function makeRepo(base: string, remote?: string): { main: string; worktree: string } {
  const main = join(base, "main");
  mkdirSync(join(main, ".git", "worktrees", "wt-b"), { recursive: true });
  writeFileSync(
    join(main, ".git", "config"),
    remote ? `[remote "origin"]\n\turl = ${remote}\n` : "[core]\n\tbare = false\n",
    "utf8",
  );
  // Linked worktree: .git is a FILE pointing into the main repo's .git dir.
  const worktree = join(base, "wt-b");
  mkdirSync(worktree, { recursive: true });
  writeFileSync(
    join(worktree, ".git"),
    `gitdir: ${join(main, ".git", "worktrees", "wt-b")}\n`,
    "utf8",
  );
  return { main, worktree };
}

describe("gitProjectKey / projectKey", () => {
  it("main repo and its linked worktree share the remote-derived key", () => {
    const base = tempDir();
    const { main, worktree } = makeRepo(base, "git@github.com:acme/rocket.git");
    expect(gitProjectKey(main)).toBe("git:github.com/acme/rocket");
    expect(gitProjectKey(worktree)).toBe("git:github.com/acme/rocket");
    // and from a subdirectory of either
    const sub = join(worktree, "src", "deep");
    mkdirSync(sub, { recursive: true });
    expect(gitProjectKey(sub)).toBe("git:github.com/acme/rocket");
  });

  it("a remote-less repo keys on its MAIN root, shared by worktrees", () => {
    const base = tempDir();
    const { main, worktree } = makeRepo(base); // no remote
    expect(gitProjectKey(main)).toBe(`gitroot:${main}`);
    expect(gitProjectKey(worktree)).toBe(`gitroot:${main}`);
  });

  it("a non-repo directory yields null; projectKey falls back to the canonical path", () => {
    const dir = tempDir();
    expect(gitProjectKey(dir)).toBeNull();
    expect(projectKey(dir)).toBe(dir);
  });

  it("never throws on garbage input or unreadable layouts", () => {
    expect(gitProjectKey("")).toBeNull();
    expect(gitProjectKey("relative/path")).toBeNull();
    const dir = tempDir();
    writeFileSync(join(dir, ".git"), "not a gitdir pointer", "utf8");
    expect(gitProjectKey(dir)).toBeNull();
    expect(projectKey(dir)).toBe(dir);
  });
});

//
// Security firewall on the kernel HTTP front door. Boots the real stack (the
// same wiring src/index.ts uses) on an ephemeral port and drives it with raw
// node:http requests so we can forge the Host header and the Content-Type the
// way a malicious cross-origin client would. Pins the production contract:
//
//   - a non-loopback Host (DNS-rebinding) is rejected 403 BEFORE any handler,
//     so whole-brain exfil via GET /memwarden/export can't reach the data;
//   - a body-bearing POST without application/json is rejected 415 BEFORE the
//     body is parsed, killing the no-preflight cross-origin write to /observe
//     and /import (memory poisoning);
//   - a well-formed loopback + JSON request still works.

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { once } from "node:events";
import { request as httpRequest, type IncomingMessage } from "node:http";
import type { AddressInfo } from "node:net";
import {
  registerWorker,
  startHttpServer,
  __resetKernelSingleton,
  type Kernel,
  type RunningHttpServer,
} from "../src/kernel/index.js";
import { isLoopbackHost } from "../src/kernel/http.js";
import { startProxyServer, type RunningProxy } from "../src/proxy/server.js";
import { StoreLibsql } from "../src/state/store-libsql.js";
import { StateKV } from "../src/state/kv.js";
import {
  registerCoreFunctions,
  getSearchIndex,
} from "../src/functions/index.js";
import { registerApiTriggers } from "../src/triggers/api.js";

let sdk: Kernel;
let http: RunningHttpServer;
let port: number;

beforeEach(async () => {
  __resetKernelSingleton();
  getSearchIndex().clear();
  sdk = registerWorker("in-process", { workerName: "memwarden-http-sec" }, {
    store: new StoreLibsql({ url: ":memory:" }),
  });
  const kv = new StateKV(sdk);
  registerCoreFunctions(sdk, kv);
  registerApiTriggers(sdk);
  http = startHttpServer(sdk, { port: 0 });
  await new Promise<void>((resolve) => {
    if (http.server.listening) resolve();
    else http.server.once("listening", () => resolve());
  });
  const addr = http.server.address() as AddressInfo;
  port = addr.port;
});

afterEach(async () => {
  await http.close().catch(() => undefined);
  await sdk.shutdown();
  __resetKernelSingleton();
});

interface Raw {
  status: number;
  body: string;
}

// Raw request so we can forge Host / Content-Type independent of the socket we
// actually connect to (always 127.0.0.1).
function rawTo(
  toPort: number,
  opts: {
    method: string;
    path: string;
    headers?: Record<string, string>;
    body?: string;
  },
): Promise<Raw> {
  return new Promise<Raw>((resolve, reject) => {
    const req = httpRequest(
      {
        host: "127.0.0.1",
        port: toPort,
        method: opts.method,
        path: opts.path,
        headers: opts.headers ?? {},
      },
      (res: IncomingMessage) => {
        const chunks: Buffer[] = [];
        res.on("data", (c: Buffer) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode ?? 0,
            body: Buffer.concat(chunks).toString("utf8"),
          }),
        );
      },
    );
    req.on("error", reject);
    if (opts.body !== undefined) req.write(opts.body);
    req.end();
  });
}

// Convenience for the kernel server (module-scoped `port`).
function raw(opts: {
  method: string;
  path: string;
  headers?: Record<string, string>;
  body?: string;
}): Promise<Raw> {
  return rawTo(port, opts);
}

