//
// QuantizedVectorIndex: API parity with VectorIndex, serialize/deserialize
// determinism with params validation, recall against the full-precision
// brute force, and rescore behavior.

import { describe, expect, it } from "vitest";
import { QuantizedVectorIndex } from "../src/functions/quantized-vector-index.js";
import { VectorIndex } from "../src/functions/vector-index.js";
import type { VectorIndexLike } from "../src/functions/types.js";
import {
  mulberry32,
  seedFromString,
} from "../src/functions/turboquant.js";

const DIMS = 256;

function gaussianSampler(seed: string): () => number {
  const prng = mulberry32(seedFromString(seed));
  let spare: number | null = null;
  return () => {
    if (spare !== null) {
      const v = spare;
      spare = null;
      return v;
    }
    let u = 0;
    while (u === 0) u = prng();
    const v = prng();
    const r = Math.sqrt(-2 * Math.log(u));
    spare = r * Math.sin(2 * Math.PI * v);
    return r * Math.cos(2 * Math.PI * v);
  };
}

// 20 gaussian cluster centers; members are center + small noise. Returns
// vectors plus a set of queries drawn near known members.
function makeClusteredDataset(opts: {
  clusters: number;
  perCluster: number;
  noise: number;
  seed: string;
}) {
  const gauss = gaussianSampler(opts.seed);
  const centers: Float32Array[] = [];
  for (let c = 0; c < opts.clusters; c++) {
    centers.push(Float32Array.from({ length: DIMS }, () => gauss()));
  }
  const vectors: Array<{ id: string; v: Float32Array }> = [];
  for (let c = 0; c < opts.clusters; c++) {
    for (let m = 0; m < opts.perCluster; m++) {
      const v = new Float32Array(DIMS);
      for (let i = 0; i < DIMS; i++) {
        v[i] = (centers[c]![i] as number) + opts.noise * gauss();
      }
      vectors.push({ id: `c${c}-m${m}`, v });
    }
  }
  return { centers, vectors, gauss };
}

function newQuantIndex(rescoreDepth: number): QuantizedVectorIndex {
  return new QuantizedVectorIndex({
    dims: DIMS,
    bits: 4,
    seed: "test-seed",
    rescoreDepth,
  });
}

describe("API parity", () => {
  it("satisfies VectorIndexLike structurally (both implementations)", () => {
    const quant: VectorIndexLike = newQuantIndex(0);
    const full: VectorIndexLike = new VectorIndex();
    for (const idx of [quant, full]) {
      expect(typeof idx.add).toBe("function");
      expect(typeof idx.remove).toBe("function");
      expect(typeof idx.search).toBe("function");
      expect(typeof idx.clear).toBe("function");
      expect(typeof idx.validateDimensions).toBe("function");
      expect(typeof idx.serialize).toBe("function");
      expect(idx.size).toBe(0);
      expect(idx.search(new Float32Array(DIMS), 5)).toEqual([]);
    }
  });

  it("returns descending {obsId, sessionId, score} rows capped at limit", () => {
    const idx = newQuantIndex(0);
    const gauss = gaussianSampler("rows");
    for (let i = 0; i < 30; i++) {
      idx.add(
        `obs-${i}`,
        `sess-${i % 3}`,
        Float32Array.from({ length: DIMS }, () => gauss()),
      );
    }
    const q = Float32Array.from({ length: DIMS }, () => gauss());
    const rows = idx.search(q, 7);
    expect(rows.length).toBe(7);
    for (let i = 1; i < rows.length; i++) {
      expect(rows[i]!.score).toBeLessThanOrEqual(rows[i - 1]!.score);
    }
    for (const r of rows) {
      expect(typeof r.obsId).toBe("string");
      expect(typeof r.sessionId).toBe("string");
      expect(Number.isFinite(r.score)).toBe(true);
    }
  });

  it("soft-skips dimension mismatches on add", () => {
    const idx = newQuantIndex(0);
    idx.add("bad", "s", new Float32Array(DIMS + 1));
    expect(idx.size).toBe(0);
    idx.add("good", "s", new Float32Array(DIMS).fill(1));
    expect(idx.size).toBe(1);
    const report = idx.validateDimensions(DIMS);
    expect(report.mismatches).toEqual([]);
    expect(Array.from(report.seenDimensions)).toEqual([DIMS]);
    expect(idx.validateDimensions(DIMS + 1).mismatches.length).toBe(1);
  });

  it("has() and ids() reflect membership on both implementations", () => {
    const quant: VectorIndexLike = newQuantIndex(0);
    const full: VectorIndexLike = new VectorIndex();
    for (const idx of [quant, full]) {
      idx.add("a", "s", new Float32Array(DIMS).fill(1));
      idx.add("b", "s", new Float32Array(DIMS).fill(2));
      expect(idx.has("a")).toBe(true);
      expect(idx.has("missing")).toBe(false);
      expect(idx.ids().sort()).toEqual(["a", "b"]);
      idx.remove("a");
      expect(idx.has("a")).toBe(false);
      expect(idx.ids()).toEqual(["b"]);
    }
  });

  it("remove and clear behave like VectorIndex", () => {
    const idx = newQuantIndex(0);
    idx.add("a", "s", new Float32Array(DIMS).fill(1));
    idx.add("b", "s", new Float32Array(DIMS).fill(2));
    idx.remove("a");
    expect(idx.size).toBe(1);
    idx.remove("a"); // idempotent
    idx.clear();
    expect(idx.size).toBe(0);
  });
});

describe("serialize / deserialize", () => {
  it("round-trips with identical search ranking", () => {
    const idx = newQuantIndex(0);
    const gauss = gaussianSampler("serde");
    for (let i = 0; i < 50; i++) {
      idx.add(
        `obs-${i}`,
        "sess",
        Float32Array.from({ length: DIMS }, () => gauss()),
      );
    }
    const q = Float32Array.from({ length: DIMS }, () => gauss());
    const before = idx.search(q, 10).map((r) => r.obsId);

    const restored = QuantizedVectorIndex.deserialize(idx.serialize());
    expect(restored).not.toBeNull();
    expect(restored!.size).toBe(50);
    expect(restored!.search(q, 10).map((r) => r.obsId)).toEqual(before);
  });

  it("rejects params drift (version, bits, seed, levelHash)", () => {
    const idx = newQuantIndex(0);
    idx.add("a", "s", new Float32Array(DIMS).fill(1));
    const payload = JSON.parse(idx.serialize()) as {
      params: Record<string, unknown>;
    };

    const mutate = (k: string, v: unknown) => {
      const copy = JSON.parse(idx.serialize()) as {
        params: Record<string, unknown>;
      };
      copy.params[k] = v;
      return QuantizedVectorIndex.deserialize(JSON.stringify(copy));
    };

    expect(mutate("version", 999)).toBeNull();
    expect(mutate("bits", 3)).toBeNull();
    expect(mutate("levelHash", "deadbeef")).toBeNull();
    expect(mutate("paddedDims", (payload.params.paddedDims as number) * 2)).toBeNull();
    expect(QuantizedVectorIndex.deserialize("not json")).toBeNull();
    // Unmutated payload stays valid.
    expect(QuantizedVectorIndex.deserialize(idx.serialize())).not.toBeNull();
  });

  it("reconcileRescoreDepth(0) drops retained full vectors", () => {
    const idx = newQuantIndex(16);
    const gauss = gaussianSampler("reconcile");
    idx.add("a", "s", Float32Array.from({ length: DIMS }, () => gauss()));
    expect(idx.serialize()).toContain('"f":'); // full vector persisted

    const restored = QuantizedVectorIndex.deserialize(idx.serialize());
    expect(restored).not.toBeNull();
    expect(restored!.params.rescoreDepth).toBe(16); // blob value wins pre-reconcile

    restored!.reconcileRescoreDepth(0);
    expect(restored!.params.rescoreDepth).toBe(0);
    expect(restored!.serialize()).not.toContain('"f":'); // memory reclaimed

    // Raising it back is allowed; entries without full vectors simply skip
    // the exact-cosine pass.
    restored!.reconcileRescoreDepth(50);
    expect(restored!.params.rescoreDepth).toBe(50);
    expect(restored!.search(new Float32Array(DIMS).fill(1), 1).length).toBe(1);
  });

  it("retains full vectors through serialization when rescoring", () => {
    const idx = newQuantIndex(10);
    const gauss = gaussianSampler("serde-full");
    const v = Float32Array.from({ length: DIMS }, () => gauss());
    idx.add("a", "s", v);
    const restored = QuantizedVectorIndex.deserialize(idx.serialize());
    expect(restored).not.toBeNull();
    // Exact-cosine rescore of the identical vector must score ~1.
    const top = restored!.search(v, 1)[0]!;
    expect(top.obsId).toBe("a");
    expect(top.score).toBeCloseTo(1, 5);
  });
});

describe("recall vs full-precision brute force", () => {
  const { vectors, gauss } = makeClusteredDataset({
    clusters: 20,
    perCluster: 100,
    noise: 0.35,
    seed: "recall",
  });

  const full = new VectorIndex();
  for (const { id, v } of vectors) full.add(id, "s", v);

  function recallAt10(idx: QuantizedVectorIndex, queries: Float32Array[]): number {
    let hit = 0;
    let total = 0;
    for (const q of queries) {
      const truth = new Set(full.search(q, 10).map((r) => r.obsId));
      const got = idx.search(q, 10);
      for (const r of got) if (truth.has(r.obsId)) hit++;
      total += truth.size;
    }
    return hit / total;
  }

  const queries: Float32Array[] = [];
  for (let i = 0; i < 40; i++) {
    const base = vectors[(i * 53) % vectors.length]!.v;
    const q = new Float32Array(DIMS);
    for (let j = 0; j < DIMS; j++) {
      q[j] = (base[j] as number) + 0.15 * gauss();
    }
    queries.push(q);
  }

  it("4-bit with rescore depth 100 reaches recall@10 >= 0.90", () => {
    const idx = newQuantIndex(100);
    for (const { id, v } of vectors) idx.add(id, "s", v);
    const r = recallAt10(idx, queries);
    expect(r).toBeGreaterThanOrEqual(0.9);
  });

  it("2-bit with rescore depth 100 stays usable (recall@10 >= 0.80, reported)", () => {
    const idx = new QuantizedVectorIndex({
      dims: DIMS,
      bits: 2,
      seed: "test-seed",
      rescoreDepth: 100,
    });
    for (const { id, v } of vectors) idx.add(id, "s", v);
    const r = recallAt10(idx, queries);
    console.log(`2-bit recall@10 with rescore 100: ${r.toFixed(3)}`);
    expect(r).toBeGreaterThanOrEqual(0.8);
  });

  it("rescore improves top-1 agreement over no-rescore", () => {
    const plain = newQuantIndex(0);
    const rescored = newQuantIndex(100);
    for (const { id, v } of vectors) {
      plain.add(id, "s", v);
      rescored.add(id, "s", v);
    }
    let plainAgree = 0;
    let rescoredAgree = 0;
    for (const q of queries) {
      const truth = full.search(q, 1)[0]!.obsId;
      if (plain.search(q, 1)[0]!.obsId === truth) plainAgree++;
      if (rescored.search(q, 1)[0]!.obsId === truth) rescoredAgree++;
    }
    // Report for visibility; assert no regression.
    console.log(
      `top-1 agreement over ${queries.length} queries — plain: ${plainAgree}, rescored: ${rescoredAgree}`,
    );
    expect(rescoredAgree).toBeGreaterThanOrEqual(plainAgree);
    expect(rescoredAgree).toBeGreaterThanOrEqual(Math.ceil(queries.length * 0.9));
  });
});

//
// Semantic runtime: makes local embeddings work after a normal install.
//
// '@huggingface/transformers' is deliberately NOT a dependency of the npm
// package — it would turn a 28MB install into a ~250MB one and slow the
// `npx memwarden audit` funnel to a crawl. Instead `memwarden up` installs
// it ONCE into <dataDir>/runtime (npm --prefix), and the embedding loader
// falls back to that location when the bare specifier doesn't resolve.
// Everything stays honest: if neither resolves, the daemon says
// "lexical-only" instead of silently degrading.

import {
  existsSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
} from "node:fs";
import { spawnSync } from "node:child_process";
import { join } from "node:path";
import { homedir } from "node:os";
import { pathToFileURL } from "node:url";

const PKG = "@huggingface/transformers";
const PKG_SPEC = "@huggingface/transformers@^3.8.1";

/** Where `memwarden up` installs the optional embedding runtime. */
export function semanticRuntimeRoot(dataDir?: string): string {
  const base =
    dataDir ?? process.env.MEMWARDEN_DATA_DIR ?? join(homedir(), ".memwarden");
  return join(base, "runtime");
}

/**
 * Locate the transformers.js Node ESM entry inside a runtime root, without
 * going through the exports map (package.json isn't an exported subpath).
 * Returns an absolute file path, or null when not installed there.
 */
export function resolveTransformersEntry(root: string): string | null {
  const pkgDir = join(root, "node_modules", "@huggingface", "transformers");
  const pkgJsonPath = join(pkgDir, "package.json");
  if (!existsSync(pkgJsonPath)) return null;
  try {
    const pkg = JSON.parse(readFileSync(pkgJsonPath, "utf8")) as {
      exports?: { node?: { import?: { default?: string } } };
      module?: string;
      main?: string;
    };
    const rel =
      pkg.exports?.node?.import?.default ?? pkg.module ?? pkg.main ?? null;
    if (!rel) return null;
    const entry = join(pkgDir, rel);
    return existsSync(entry) ? entry : null;
  } catch {
    return null;
  }
}

/**
 * Import transformers.js: bare specifier first (dev checkouts, users who
 * installed it themselves), then the memwarden runtime dir. Throws with an
 * actionable message when neither resolves.
 */
export async function importTransformers(): Promise<{ pipeline?: unknown }> {
  const specifier = PKG;
  try {
    return (await import(specifier)) as { pipeline?: unknown };
  } catch {
    // fall through to the runtime root
  }
  const entry = resolveTransformersEntry(semanticRuntimeRoot());
  if (entry) {
    const mod = (await import(pathToFileURL(entry).href)) as {
      pipeline?: unknown;
      default?: { pipeline?: unknown };
    };
    // Tolerate CJS/ESM interop: pipeline may sit on the default export.
    if (typeof mod.pipeline === "function") return mod;
    if (typeof mod.default?.pipeline === "function") return mod.default;
    return mod;
  }
  throw new Error(
    `Local embeddings require '${PKG}'. Run 'memwarden up' to install it ` +
      `into ${semanticRuntimeRoot()}, or: npm install ${PKG}`,
  );
}

export interface RuntimeInstallResult {
  ok: boolean;
  message: string;
}

/**
 * Install the embedding runtime under <dataDir>/runtime via npm --prefix.
 * Synchronous on purpose: `up` is an interactive command and the install is
 * its longest step — stream npm's own progress to the terminal.
 */
export function installSemanticRuntime(dataDir?: string): RuntimeInstallResult {
  const root = semanticRuntimeRoot(dataDir);
  const args = [
    "install",
    "--prefix",
    root,
    "--no-fund",
    "--no-audit",
    "--loglevel=error",
    PKG_SPEC,
  ];
  // npm is npm.cmd on Windows and .cmd files only run through a shell.
  const win = process.platform === "win32";
  const r = spawnSync(win ? "npm.cmd" : "npm", win ? args.map(quoteWin) : args, {
    stdio: ["ignore", "inherit", "inherit"],
    shell: win,
    timeout: 10 * 60 * 1000,
  });
  if (r.error) return { ok: false, message: r.error.message };
  if (r.status !== 0) return { ok: false, message: `npm exited ${r.status}` };
  if (!resolveTransformersEntry(root)) {
    return { ok: false, message: `npm succeeded but ${PKG} is not resolvable in ${root}` };
  }
  const freed = pruneSemanticRuntime(root);
  return {
    ok: true,
    message: freed > 0 ? `${root} (pruned ${mib(freed)} of unusable binaries)` : root,
  };
}

function mib(bytes: number): string {
  return `${Math.round(bytes / (1024 * 1024))}MB`;
}

/** Recursive delete that reports how many bytes went away. */
function rmReport(target: string): number {
  let freed = 0;
  try {
    const st = statSync(target);
    if (st.isDirectory()) {
      for (const e of readdirSync(target)) freed += rmReport(join(target, e));
    } else {
      freed += st.size;
    }
    rmSync(target, { recursive: true, force: true });
  } catch {
    // best-effort: a runtime we cannot prune still works, just larger
  }
  return freed;
}

/**
 * Delete the parts of the embedding runtime that can never execute here.
 *
 * `npm install @huggingface/transformers` pulls onnxruntime for EVERY target:
 * measured on a darwin/arm64 install, 425MB of runtime contained 86MB of
 * `onnxruntime-web` (a browser build Node never loads) and ~145MB of native
 * libraries for linux-x64, linux-arm64, win32-x64, win32-arm64 and darwin-x64.
 * None of it is reachable, and a resident daemon quietly holding a quarter
 * gigabyte of dead weight is a bad neighbour on someone's laptop.
 *
 * Only the current platform/arch pair is kept. Moving the brain to a different
 * OS means re-running `memwarden up`, which reinstalls the runtime; until then
 * the loader falls back to BM25 and says so, which is the existing honest
 * degradation path rather than a new failure mode.
 *
 * MEMWARDEN_RUNTIME_PRUNE=off keeps everything.
 */
export function pruneSemanticRuntime(root: string): number {
  if ((process.env["MEMWARDEN_RUNTIME_PRUNE"] ?? "").toLowerCase() === "off") {
    return 0;
  }
  const modules = join(root, "node_modules");
  let freed = 0;

  // The browser build. Node resolves onnxruntime-node; this is never loaded.
  freed += rmReport(join(modules, "onnxruntime-web"));

  // Native libraries for other targets. The layout is
  // onnxruntime-node/bin/napi-v3/<platform>/<arch>/...
  const binRoot = join(modules, "onnxruntime-node", "bin");
  let napiDirs: string[] = [];
  try {
    napiDirs = readdirSync(binRoot).map((d) => join(binRoot, d));
  } catch {
    napiDirs = [];
  }
  for (const napi of napiDirs) {
    let platforms: string[] = [];
    try {
      platforms = readdirSync(napi);
    } catch {
      continue;
    }
    for (const plat of platforms) {
      if (plat !== process.platform) {
        freed += rmReport(join(napi, plat));
        continue;
      }
      // Right platform: drop the other architectures.
      const platDir = join(napi, plat);
      let arches: string[] = [];
      try {
        arches = readdirSync(platDir);
      } catch {
        continue;
      }
      for (const arch of arches) {
        if (arch !== process.arch) freed += rmReport(join(platDir, arch));
      }
    }
  }
  return freed;
}

// Windows shell invocation: quote anything with spaces (e.g. the --prefix
// path under C:\Users\First Last\...).
function quoteWin(a: string): string {
  return /[\s"]/.test(a) ? `"${a.replace(/"/g, '\\"')}"` : a;
}

const TURBOVEC_PKG = "@memwarden/turbovec";

/** Is the native vector engine already present in the runtime dir? */
export function turbovecInstalled(dataDir?: string): boolean {
  return existsSync(
    join(semanticRuntimeRoot(dataDir), "node_modules", "@memwarden", "turbovec"),
  );
}

/**
 * Install the optional native vector engine into <dataDir>/runtime. Quiet:
 * npm output is captured, not streamed — an unpublished package or an
 * offline machine is a normal outcome the caller reports honestly, not an
 * error wall. The daemon's boot probe remains the source of truth for which
 * engine actually serves.
 */
export function installTurbovecRuntime(dataDir?: string): RuntimeInstallResult {
  const root = semanticRuntimeRoot(dataDir);
  const args = [
    "install",
    "--prefix",
    root,
    "--no-fund",
    "--no-audit",
    "--loglevel=error",
    `${TURBOVEC_PKG}@^0.1`,
  ];
  const win = process.platform === "win32";
  const r = spawnSync(win ? "npm.cmd" : "npm", win ? args.map(quoteWin) : args, {
    stdio: ["ignore", "pipe", "pipe"],
    shell: win,
    timeout: 5 * 60 * 1000,
  });
  if (r.error) return { ok: false, message: r.error.message };
  if (r.status !== 0) {
    const err = (r.stderr?.toString() ?? "").trim();
    return {
      ok: false,
      message: /E404|404 Not Found/i.test(err)
        ? "not yet published to npm"
        : `npm exited ${r.status}`,
    };
  }
  return turbovecInstalled(dataDir)
    ? { ok: true, message: root }
    : { ok: false, message: `npm succeeded but ${TURBOVEC_PKG} is not present in ${root}` };
}

//
// Dependency-free MCP server for memwarden. A hand-rolled JSON-RPC 2.0
// dispatcher over stdio — no @modelcontextprotocol/sdk — so the core stays
// lean and self-contained, and the dispatcher is unit-testable without a
// host or a pipe. It proxies to a running memwarden daemon over HTTP, so
// every MCP client (Claude Code, Cursor, Claude Desktop, Cline, Windsurf)
// shares the one local brain.
//
// Beyond the usual save/search/context tools, it exposes the two memwarden
// has and others don't: memory_verify (tamper-evident oplog integrity) and
// memory_stats (live TurboQuant compression ratio).
//
// It also exposes an MCP *prompt*, `recall`, which clients surface as a
// slash command (in Claude Code: `/mcp__memwarden__recall <query>`). The
// user types it mid-chat, the server searches the project's memory and
// returns the matching context as a message the client injects into the
// conversation — on-demand recall from within any MCP-aware tool.

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { canonicalizePath } from "../functions/paths.js";
import { frameMemoryBlock } from "../functions/injection-format.js";

const PROTOCOL_VERSION = "2024-11-05";
const SERVER_NAME = "memwarden";
const SERVER_VERSION = (() => {
  try {
    const pkg = JSON.parse(
      readFileSync(
        join(dirname(fileURLToPath(import.meta.url)), "..", "..", "package.json"),
        "utf8",
      ),
    ) as { version?: string };
    return pkg.version ?? "unknown";
  } catch {
    return "unknown";
  }
})();

// Backward-compatible session metadata for memory_remember calls that name
// none. Hashing the canonical project path keeps the metadata project-scoped
// instead of reintroducing the old shared literal "mcp" session id.
export function projectScopedSessionId(prefix: string, project: string): string {
  const hash = createHash("sha256")
    .update(canonicalizePath(project))
    .digest("hex")
    .slice(0, 12);
  return `${prefix}-${hash}`;
}

export interface McpServerOptions {
  baseUrl: string; // e.g. http://localhost:3111
  secret?: string;
  fetchFn?: typeof fetch; // injectable for tests
  // Working directory this MCP server was launched in. MCP clients launch
  // the server inside the workspace, so this is the project the agent is
  // in — used to auto-scope recall so the agent never has to name it.
  cwd?: string;
  // Self-heal hook: called when a daemon request fails with a network error
  // (daemon down). The bin wires this to ensureDaemon so a dead daemon is
  // revived on demand and the request retried — no human in the loop.
  ensureUp?: () => Promise<void>;
}

interface JsonRpcRequest {
  jsonrpc: "2.0";
  id?: string | number | null;
  method: string;
  params?: unknown;
}

interface JsonRpcResponse {
  jsonrpc: "2.0";
  id: string | number | null;
  result?: unknown;
  error?: { code: number; message: string };
}

interface ToolDef {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  call(args: Record<string, unknown>): Promise<unknown>;
}

function str(v: unknown, fallback = ""): string {
  return typeof v === "string" && v.length > 0 ? v : fallback;
}

export function createMcpServer(opts: McpServerOptions) {
  const base = opts.baseUrl.replace(/\/$/, "");
  const doFetch = opts.fetchFn ?? fetch;
  const serverCwd = opts.cwd ?? process.cwd();

  async function api(
    method: "GET" | "POST",
    path: string,
    body?: unknown,
  ): Promise<unknown> {
    const headers: Record<string, string> = { "content-type": "application/json" };
    if (opts.secret) headers["authorization"] = `Bearer ${opts.secret}`;
    const init = {
      method,
      headers,
      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
    };
    // One self-heal retry: a network error means the daemon is down; revive
    // it and try again so the user's request just works.
    for (let attempt = 0; ; attempt++) {
      try {
        const res = await doFetch(`${base}${path}`, init);
        const text = await res.text();
        // An HTTP error must NOT look like an empty-but-successful result —
        // otherwise a secured daemon's 401 (secret missing/mismatched in this
        // process) silently reads as "no memory" and auto-recall dies with no
        // sign of the real cause. Surface it as a thrown error the tool layer
        // turns into a visible isError result.
        if (!res.ok) {
          const detail =
            res.status === 401
              ? "unauthorized — the daemon requires a secret this MCP server can't resolve " +
                "(set MEMWARDEN_SECRET or ensure <dataDir>/secret is readable)"
              : `daemon returned HTTP ${res.status}`;
          throw new Error(`memwarden ${path}: ${detail}`);
        }
        try {
          return JSON.parse(text);
        } catch {
          return { raw: text, status: res.status };
        }
      } catch (err) {
        // Retry once only on a genuine network error (daemon down). An HTTP
        // error (e.g. 401) is deterministic — reviving the daemon won't fix
        // it, so don't loop; rethrow.
        const isNetworkError = !(err instanceof Error && err.message.startsWith("memwarden "));
        if (attempt === 0 && isNetworkError && opts.ensureUp) {
          await opts.ensureUp();
          continue;
        }
        throw err;
      }
    }
  }

  const tools: ToolDef[] = [
    {
      name: "memory_resume",
      description:
        "Recall what was being worked on in THIS project, across every past session and every agent (Claude, Codex, Cursor, …). Call this whenever the user references earlier work — e.g. 'continue what we were doing', 'review the project Claude and I built', 'what was I working on here', 'pick up from the last session'. Returns a narrative digest of the relevant prior context, already scoped to the current working directory, ready to act on.",
      inputSchema: {
        type: "object",
        properties: {
          query: {
            type: "string",
            description:
              "What to focus the recall on (e.g. 'the auth refactor', 'review the project'). Optional but improves relevance.",
          },
          cwd: {
            type: "string",
            description:
              "Working directory to scope to. Defaults to where this server was launched (the current project).",
          },
          token_budget: <REDACTED>
            type: "number",
            description: "Max tokens of context to return (default 2000).",
          },
        },
      },
      call: (a) =>
        api("POST", "/memwarden/search", {
          query: str(a["query"], "what was I working on"),
          cwd: str(a["cwd"], serverCwd),
          format: "narrative",
          limit: 20,
          safe_only: true, // Verified Recall: never resume stale memory
          ...(typeof a["token_budget"] === "number"
            ? { token_budget: <REDACTED>"token_budget"] }
            : { token_budget: <REDACTED> }),
        }),
    },
    {
      name: "memory_remember",
      description:
        "Explicitly save a durable manual memory for this project. It survives ordinary retention without needing to be recalled. Supplied files are hashed now for Verified Recall; file-less saves remain honestly labeled sourced but unverified.",
      inputSchema: {
        type: "object",
        properties: {
          text: { type: "string", description: "The content to remember" },
          title: {
            type: "string",
            description: "Optional human title. Defaults to the first content line.",
          },
          kind: {
            type: "string",
            enum: ["fact", "preference", "pattern", "architecture", "bug", "workflow"],
            description: "Memory kind (default fact).",
          },
          files: {
            type: "array",
            items: { type: "string" },
            description:
              "Optional files under the current project to hash as source evidence.",
          },
          expires_at: {
            anyOf: [{ type: "string", format: "date-time" }, { type: "null" }],
            description: "Optional explicit expiry. Null or omitted means durable.",
          },
          expiry: {
            anyOf: [{ type: "string", format: "date-time" }, { type: "null" }],
            description: "Alias for expires_at.",
          },
          supersedes: {
            type: "string",
            description: "Optional memory id this save replaces and archives.",
          },
          sessionId: { type: "string", description: "Optional session id" },
          project: {
            type: "string",
            description:
              "Optional project directory. Defaults to where this server was launched (the current project).",
          },
        },
        required: ["text"],
      },
      // Scope to the server's launch directory by default. The fallback
      // session remains project-specific for backward-compatible metadata,
      // while the manual memory itself is stored directly in KV.memories.
      call: (a) => {
        const project = str(a["project"], serverCwd);
        const hasExpiresAt = Object.prototype.hasOwnProperty.call(a, "expires_at");
        const hasExpiry = Object.prototype.hasOwnProperty.call(a, "expiry");
        const expiry = hasExpiresAt ? a["expires_at"] : hasExpiry ? a["expiry"] : undefined;
        return api("POST", "/memwarden/remember", {
          text: typeof a["text"] === "string" ? a["text"] : "",
          sessionId: str(a["sessionId"], projectScopedSessionId("mcp", project)),
          project,
          agent: "mcp",
          ...(typeof a["title"] === "string" ? { title: a["title"] } : {}),
          ...(typeof a["kind"] === "string" ? { kind: a["kind"] } : {}),
          ...(a["files"] !== undefined ? { files: a["files"] } : {}),
          ...(hasExpiresAt || hasExpiry ? { expires_at: expiry } : {}),
          ...(typeof a["supersedes"] === "string"
            ? { supersedes: a["supersedes"] }
            : {}),
        });
      },
    },
    {
      name: "memory_search",
      description:
        "Search memories by meaning and keywords (TurboQuant vector + BM25 hybrid). " +
        "Every result is trust/source-labeled. Defaults to current, firewalled memory in this project; " +
        "source-drifted or superseded records require mode='historical'/'all' (or include_drifted=true).",
      inputSchema: {
        type: "object",
        properties: {
          query: { type: "string", description: "What to look for" },
          limit: { type: "number", description: "Max results (default 10)" },
          mode: {
            type: "string",
            enum: ["current", "historical", "all"],
            description:
              "Inclusion policy: current (default, safe), historical (only source-drifted/superseded), or all (both). Classification and labels always run.",
          },
          include_drifted: {
            type: "boolean",
            description:
              "Compatibility shorthand: true means mode='all'; false means mode='current'.",
          },
          trust: {
            type: "array",
            items: {
              type: "string",
              enum: [
                "source-verified",
                "source-cosmetic",
                "sourced",
                "unsourced",
                "source-drifted",
                "unverifiable",
              ],
            },
            description:
              "Optional source-status allowlist, including source-cosmetic for normalized-only current matches.",
          },
          format: {
            type: "string",
            enum: ["full", "compact", "narrative"],
            description: "Result shape (default full); every shape carries source status.",
          },
          all_projects: {
            type: "boolean",
            description:
              "Search across every project instead of just this one. Each hit is checked against its own known checkout; unavailable checkouts are labeled unverifiable and excluded from current mode.",
          },
        },
        required: ["query"],
      },
      // Project-scoped and current by default. all_projects is an explicit
      // cross-repo lookup, but it never verifies a hit against this server's
      // unrelated cwd; the daemon classifies against each hit's own checkout.
      call: (a) => {
        const requestedMode =
          typeof a["mode"] === "string" ? a["mode"].trim().toLowerCase() : undefined;
        const aliasMode =
          a["include_drifted"] === true
            ? "all"
            : a["include_drifted"] === false
              ? "current"
              : undefined;
        if (requestedMode && aliasMode && requestedMode !== aliasMode) {
          throw new Error(
            "memory_search: mode conflicts with include_drifted (true means all; false means current)",
          );
        }
        const mode = requestedMode ?? aliasMode ?? "current";
        return api("POST", "/memwarden/search", {
          query: str(a["query"]),
          limit: typeof a["limit"] === "number" ? a["limit"] : 10,
          mode,
          ...(typeof a["format"] === "string" ? { format: a["format"] } : {}),
          ...(Array.isArray(a["trust"]) ? { trust: a["trust"] } : {}),
          ...(a["all_projects"] === true ? {} : { cwd: serverCwd }),
        });
      },
    },
    {
      name: "memory_context",
      description:
        "Pack the most relevant prior memory for this project into a context block under a token budget.",
      inputSchema: {
        type: "object",
        properties: {
          query: { type: "string", description: "Optional focus query" },
          cwd: { type: "string", description: "Working directory to scope to (defaults to this project)" },
          token_budget: <REDACTED> type: "number", description: "Optional token budget" },
        },
      },
      // Routes through the project-scoped narrative search rather than
      // /context (which needs a sessionId+project the MCP layer doesn't
      // have). Returns a packed, budgeted context block.
      call: (a) =>
        api("POST", "/memwarden/search", {
          query: str(a["query"], "relevant context for this project"),
          cwd: str(a["cwd"], serverCwd),
          format: "narrative",
          limit: 20,
          safe_only: true, // Verified Recall: never inject stale memory
          ...(typeof a["token_budget"] === "number"
            ? { token_budget: <REDACTED>"token_budget"] }
            : { token_budget: <REDACTED> }),
        }),
    },
    {
      name: "dejafix_lookup",
      description:
        "Déjà Fix: before you try to fix an error, check if ANY agent (Claude, Codex, Cursor, …) already solved this exact error in THIS project. Paste the error message, stack trace, or failing-test output. Returns matching fixes that are still valid — each verified against the live repo (a fix whose files changed or vanished is suppressed, never surfaced) and badged 'verified current' or 'sourced, unverified'. Call this whenever you hit an error before debugging from scratch.",
      inputSchema: {
        type: "object",
        properties: {
          error_text: {
            type: "string",
            description:
              "The error message, stack trace, or failing-test output to look up.",
          },
          cwd: {
            type: "string",
            description:
              "Working directory to scope to. Defaults to where this server was launched (the current project).",
          },
        },
        required: ["error_text"],
      },
      call: (a) =>
        api("POST", "/memwarden/dejafix/lookup", {
          error_text: str(a["error_text"]),
          cwd: str(a["cwd"], serverCwd),
        }),
    },
    {
      name: "dejafix_record",
      description:
        "Déjà Fix: record how an error was resolved so any agent that hits it again can recall the fix. Provide the original error text and a short fix narrative; optionally a root cause and the files the fix touched (hashed now so stale fixes are auto-suppressed later). Call this right after you resolve a non-trivial error.",
      inputSchema: {
        type: "object",
        properties: {
          error_text: {
            type: "string",
            description: "The error message/stack trace that was resolved.",
          },
          fix: {
            type: "string",
            description: "Short narrative of the fix that resolved it.",
          },
          root_cause: {
            type: "string",
            description: "Optional one-line root cause.",
          },
          files: {
            type: "array",
            items: { type: "string" },
            description:
              "Files the fix touched/relied on (relative to cwd). Hashed for drift detection.",
          },
          cwd: {
            type: "string",
            description:
              "Working directory to scope to. Defaults to where this server was launched.",
          },
        },
        required: ["error_text", "fix"],
      },
      call: (a) =>
        api("POST", "/memwarden/dejafix/record", {
          error_text: str(a["error_text"]),
          fix: str(a["fix"]),
          ...(typeof a["root_cause"] === "string" && a["root_cause"]
            ? { root_cause: a["root_cause"] }
            : {}),
          ...(Array.isArray(a["files"])
            ? {
                files: (a["files"] as unknown[]).filter(
                  (f): f is string => typeof f === "string",
                ),
              }
            : {}),
          cwd: str(a["cwd"], serverCwd),
        }),
    },
    {
      name: "memory_verify",
      description:
        "Check the oplog hash chain is intact: tamper-EVIDENT integrity. Detects edits and reorders within the memory log (not tamper-proof: there is no signing yet, and truncating the newest entries is not detectable).",
      inputSchema: { type: "object", properties: {} },
      call: () => api("GET", "/memwarden/verify"),
    },
    {
      name: "memory_stats",
      description:
        "Report memory counts, the active embedding model, and the live TurboQuant compression ratio.",
      inputSchema: { type: "object", properties: {} },
      call: () => api("GET", "/memwarden/stats"),
    },
  ];

  const toolByName = new Map(tools.map((t) => [t.name, t]));

  // MCP prompts. Clients surface these as slash commands; `recall` is the
  // on-demand "pull my memory into this chat" command the whole layer is for.
  const prompts = [
    {
      name: "recall",
      description:
        "Pull relevant memory from past sessions into THIS chat. Give it what you're working on (e.g. 'the auth refactor'); it searches your memwarden brain — scoped to the current project — and injects the matching context.",
      arguments: [
        {
          name: "query",
          description:
            "What to recall (e.g. 'auth refactor', 'the proxy work'). Optional — omit to resume the project broadly.",
          required: false,
        },
      ],
    },
  ];

  async function recallText(query: string): Promise<string> {
    try {
      const result = (await api("POST", "/memwarden/search", {
        query,
        cwd: serverCwd,
        format: "narrative",
        limit: 20,
        token_budget: <REDACTED>
        safe_only: true, // Verified Recall: /recall never injects stale memory
      })) as { text?: string };
      return typeof result.text === "string" ? result.text : "";
    } catch {
      return "";
    }
  }

  function ok(id: JsonRpcResponse["id"], result: unknown): JsonRpcResponse {
    return { jsonrpc: "2.0", id, result };
  }
  function fail(
    id: JsonRpcResponse["id"],
    code: number,
    message: string,
  ): JsonRpcResponse {
    return { jsonrpc: "2.0", id, error: { code, message } };
  }

  // Returns the response, or null for notifications (no id / initialized).
  async function dispatch(
    req: JsonRpcRequest,
  ): Promise<JsonRpcResponse | null> {
    const id = req.id ?? null;
    switch (req.method) {
      case "initialize":
        return ok(id, {
          protocolVersion: PROTOCOL_VERSION,
          capabilities: { tools: {}, prompts: {} },
          serverInfo: { name: SERVER_NAME, version: SERVER_VERSION },
        });
      case "notifications/initialized":
      case "initialized":
        return null;
      case "ping":
        return ok(id, {});
      case "tools/list":
        return ok(id, {
          tools: tools.map((t) => ({
            name: t.name,
            description: t.description,
            inputSchema: t.inputSchema,
          })),
        });
      case "prompts/list":
        return ok(id, { prompts });
      case "prompts/get": {
        const params = (req.params ?? {}) as {
          name?: string;
          arguments?: Record<string, unknown>;
        };
        if (params.name !== "recall") {
          return fail(id, -32602, `unknown prompt: ${params.name}`);
        }
        const query = str(
          params.arguments?.["query"],
          "what was I working on in this project",
        );
        const text = await recallText(query);
        // Same shared framing + delimiter defense as every other injection
        // surface: recalled content is DATA, and an embedded closing marker
        // cannot break out of the block.
        const body = text
          ? `Relevant memory recalled by memwarden (scoped to this project) for "${query}".\n` +
            frameMemoryBlock(text)
          : `No relevant memory found for "${query}".`;
        return ok(id, {
          description: `memwarden recall: ${query}`,
          messages: [{ role: "user", content: { type: "text", text: body } }],
        });
      }
      case "tools/call": {
        const params = (req.params ?? {}) as {
          name?: string;
          arguments?: Record<string, unknown>;
        };
        const tool = params.name ? toolByName.get(params.name) : undefined;
        if (!tool) return fail(id, -32602, `unknown tool: ${params.name}`);
        try {
          const result = await tool.call(params.arguments ?? {});
          return ok(id, {
            content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
          });
        } catch (err) {
          return ok(id, {
            isError: true,
            content: [
              {
                type: "text",
                text: `memory tool error: ${
                  err instanceof Error ? err.message : String(err)
                }`,
              },
            ],
          });
        }
      }
      default:
        if (id === null) return null; // unknown notification
        return fail(id, -32601, `method not found: ${req.method}`);
    }
  }

  return {
    dispatch,
    toolNames: () => tools.map((t) => t.name),
    promptNames: () => prompts.map((p) => p.name),
  };
}

export type McpServer = ReturnType<typeof createMcpServer>;

/**
 * Wire a server to newline-delimited JSON-RPC over stdin/stdout. Kept thin
 * and separate from dispatch() so the protocol logic stays testable.
 */
export function runStdio(server: McpServer): void {
  let buffer = "";
  process.stdin.setEncoding("utf8");
  process.stdin.on("data", (chunk: string) => {
    buffer += chunk;
    let nl: number;
    while ((nl = buffer.indexOf("\n")) >= 0) {
      const line = buffer.slice(0, nl).trim();
      buffer = buffer.slice(nl + 1);
      if (!line) continue;
      let req: JsonRpcRequest;
      try {
        req = JSON.parse(line) as JsonRpcRequest;
      } catch {
        continue;
      }
      void server.dispatch(req).then((res) => {
        if (res) process.stdout.write(JSON.stringify(res) + "\n");
      });
    }
  });
}

