// --- AGENTS.md: instruction-driven auto-recall ---------------------
//
// Tools without a hook system (Cursor, Antigravity, OpenCode, …) can't be
// made to auto-recall mechanically. The cross-tool lever is AGENTS.md (the
// Linux Foundation standard read by Cursor, Gemini/Antigravity, OpenCode,
// Codex): a project instruction telling the agent to use the memory tools at
// task boundaries. Soft (the agent must follow it) but it is how the
// ecosystem gets automatic behavior without hooks.

const AGENTS_START = "<!-- memwarden:start -->";
const AGENTS_END = "<!-- memwarden:end -->";

export function memwardenAgentsBlock(): string {
  return [
    AGENTS_START,
    "## Memory — always use it (memwarden)",
    "",
    "This project has shared, cross-tool memory (memwarden). Treat it as part of every task, automatically, without being asked:",
    "",
    "1. **Before starting any task**, call the `memory_resume` tool (or `/recall`) to load what past sessions — in Claude Code, Codex, Cursor, or any other tool — already learned here.",
    "2. **Whenever you learn something durable** (a decision, a fix, how something works, a preference), call `memory_remember` to save it.",
    "",
    "What you save is available in every tool, so always recall first and save as you go.",
    AGENTS_END,
    "",
  ].join("\n");
}

/** Insert/replace the memwarden block in an AGENTS.md body. Idempotent. */
export function mergeAgentsMd(existing: string | null): string {
  const block = memwardenAgentsBlock();
  if (!existing || !existing.trim()) return `# AGENTS.md\n\n${block}`;
  const start = existing.indexOf(AGENTS_START);
  const end = existing.indexOf(AGENTS_END);
  if (start !== -1 && end !== -1 && end > start) {
    return (
      existing.slice(0, start) +
      block.trimEnd() +
      existing.slice(end + AGENTS_END.length)
    );
  }
  return existing.replace(/\s*$/, "") + "\n\n" + block;
}

export function writeAgentsMd(dir: string): { path: string; created: boolean } {
  const path = join(dir, "AGENTS.md");
  const created = !existsSync(path);
  const existing = created ? null : readFileSync(path, "utf8");
  writeFileSync(path, mergeAgentsMd(existing), "utf8");
  return { path, created };
}

/** Strip the memwarden block from an AGENTS.md body. Pure; null = no block. */
export function unmergeAgentsMd(existing: string): string | null {
  const start = existing.indexOf(AGENTS_START);
  const end = existing.indexOf(AGENTS_END);
  if (start === -1 || end === -1 || end <= start) return null;
  const before = existing.slice(0, start).replace(/\n+$/, "\n");
  const after = existing.slice(end + AGENTS_END.length).replace(/^\n+/, "\n");
  const merged = (before + after).replace(/\n{3,}/g, "\n\n");
  return merged.trim() ? merged : "";
}

/**
 * Remove the memwarden block from AGENTS.md. Only the sentinel-marked block
 * is touched; a file that becomes empty is deleted (we created it).
 */
export function removeAgentsMd(dir: string): { path: string; removed: boolean } {
  const path = join(dir, "AGENTS.md");
  if (!existsSync(path)) return { path, removed: false };
  const existing = readFileSync(path, "utf8");
  const next = unmergeAgentsMd(existing);
  if (next === null) return { path, removed: false };
  // "# AGENTS.md" alone is the header we wrote around our block — treat a
  // header-only remainder as empty too.
  if (!next || next.trim() === "# AGENTS.md") {
    rmSync(path);
  } else {
    writeFileSync(path, next, "utf8");
  }
  return { path, removed: true };
}

export interface WireResult {
  id: string;
  label: string;
  path: string;
  status: "wired" | "skipped";
  reason?: string;
}

/**
 * Write/merge the memwarden MCP server into one tool's config. Safe by
 * default: if the existing file cannot be parsed, it is left untouched and
 * the result is reported as skipped (never clobbered).
 */
export function writeTool(
  adapter: ToolAdapter,
  home: string,
  launch: LaunchInfo,
): WireResult {
  const path = adapter.configPath(home);
  let existing: string | null = null;
  if (existsSync(path)) {
    try {
      existing = readFileSync(path, "utf8");
    } catch (err) {
      return {
        id: adapter.id,
        label: adapter.label,
        path,
        status: "skipped",
        reason: `could not read (${err instanceof Error ? err.message : err})`,
      };
    }
  }
  let next: string;
  try {
    next = adapter.merge(existing, launch);
  } catch {
    return {
      id: adapter.id,
      label: adapter.label,
      path,
      status: "skipped",
      reason: "existing config is not valid JSON — left untouched",
    };
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, next, "utf8");
  // The launch env we merged in carries the daemon bearer secret — keep the
  // config owner-only (default 0644 would expose it to other local users).
  try {
    chmodSync(path, 0o600);
  } catch {
    // best-effort; some filesystems reject chmod
  }
  return { id: adapter.id, label: adapter.label, path, status: "wired" };
}

export interface UnwireResult {
  id: string;
  label: string;
  path: string;
  status: "removed" | "skipped";
  reason?: string;
}

/**
 * Remove the memwarden MCP server from one tool's config. Same safety rule
 * as writeTool: an unparseable config is left untouched and reported, never
 * clobbered.
 */
export function unwireTool(adapter: ToolAdapter, home: string): UnwireResult {
  const path = adapter.configPath(home);
  const base = { id: adapter.id, label: adapter.label, path };
  if (!existsSync(path)) {
    return { ...base, status: "skipped", reason: "no config file" };
  }
  let existing: string;
  try {
    existing = readFileSync(path, "utf8");
  } catch (err) {
    return {
      ...base,
      status: "skipped",
      reason: `could not read (${err instanceof Error ? err.message : err})`,
    };
  }
  let next: string | null;
  try {
    next = adapter.unmerge(existing);
  } catch {
    return {
      ...base,
      status: "skipped",
      reason: "existing config is not valid JSON — left untouched",
    };
  }
  if (next === null) {
    return { ...base, status: "skipped", reason: "not wired" };
  }
  writeFileSync(path, next, "utf8");
  return { ...base, status: "removed" };
}

/**
 * Is memwarden present in this tool's config right now? "unknown" means the
 * config exists but cannot be parsed.
 */
export function toolWireState(
  adapter: ToolAdapter,
  home: string,
): "wired" | "not wired" | "unknown" {
  const path = adapter.configPath(home);
  if (!existsSync(path)) return "not wired";
  try {
    return adapter.unmerge(readFileSync(path, "utf8")) === null
      ? "not wired"
      : "wired";
  } catch {
    return "unknown";
  }
}

//
// OS service installer — the crash/reboot self-heal. Registers the daemon
// with the platform supervisor so it starts at login and restarts if it
// dies, with no human in the loop:
//   macOS  ~/Library/LaunchAgents/ai.memwarden.daemon.plist  (launchd)
//   Linux  ~/.config/systemd/user/memwarden.service          (systemd --user)
//
// KeepAlive/Restart are set to "restart on FAILURE only" (SuccessfulExit
// false / on-failure). That pairs with the daemon's clean exit(0) on
// EADDRINUSE: if another instance already holds the port, the supervised one
// exits cleanly and is NOT relaunched (no crash loop); a real crash (non-zero
// exit) IS relaunched. Best-effort: any failure returns ok:false so `up`
// falls back to a detached spawn.

import { execFileSync } from "node:child_process";
import { chmodSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { DAEMON_ENTRY } from "./ensure.js";
import {
  DAEMON_LOG_MODE_ENV,
  DAEMON_LOG_MODE_FILE,
  DAEMON_LOG_MODE_JOURNALD,
  daemonLogPath,
  openSecureDaemonLog,
} from "./log.js";

const LABEL = "ai.memwarden.daemon";

export interface ServiceResult {
  kind: "launchd" | "systemd" | "unsupported";
  ok: boolean;
  path?: string;
  message: string;
}

type ServiceCommand = (command: string, args: string[]) => void;

interface ServiceRuntime {
  platform: NodeJS.Platform;
  home: string;
  node: string;
  run: ServiceCommand;
}

/** Test-only runtime: lets launchd installation stay entirely below a temp HOME. */
export interface ServiceTestRuntime {
  platform: NodeJS.Platform;
  home: string;
  node?: string;
  run?: ServiceCommand;
}

function productionRuntime(): ServiceRuntime {
  return {
    platform: process.platform,
    home: homedir(),
    node: process.execPath,
    run: (command, args) => {
      execFileSync(command, args, { stdio: "ignore" });
    },
  };
}

function errMsg(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

function plistPath(home: string): string {
  return join(home, "Library", "LaunchAgents", `${LABEL}.plist`);
}
function systemdPath(home: string): string {
  return join(home, ".config", "systemd", "user", "memwarden.service");
}

// XML-escape a value before interpolating it into the plist (the secret is
// base64url so it has no XML metacharacters, but be defensive).
function xmlEscape(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

// Tuning env vars the managed daemon must inherit from the `up` invocation —
// without this, `MEMWARDEN_VECTOR_BACKEND=turbovec memwarden up` installs a
// service that silently runs the default backend. Values are restricted to a
// safe charset since they land inside a plist/systemd unit.
const TUNING_ENV_KEYS = [
  "MEMWARDEN_VECTOR_BACKEND",
  "MEMWARDEN_EMBED_DTYPE",
  "MEMWARDEN_EMBEDDING_PROVIDER",
  "MEMWARDEN_QUANT_VECTOR",
  "MEMWARDEN_QUANT_BITS",
  "MEMWARDEN_QUANT_RESCORE",
  "MEMWARDEN_QUANT_SEED",
  "MEMWARDEN_PROXY_PORT",
  "MEMWARDEN_REST_PORT",
] as const;

/** Test-only export: the tuning-env passthrough with its charset guard. */
export function __tuningEnvForTests(): Array<[string, string]> {
  return tuningEnv();
}

function tuningEnv(): Array<[string, string]> {
  const out: Array<[string, string]> = [];
  for (const key of TUNING_ENV_KEYS) {
    const v = process.env[key];
    if (v && /^[A-Za-z0-9._:/-]+$/.test(v)) out.push([key, v]);
  }
  return out;
}

function macPlist(node: string, dataDir: string, secret?: string): string {
  const log = daemonLogPath(dataDir);
  // The managed daemon resolves its auth secret from MEMWARDEN_SECRET, so it
  // must be in the service environment or a login-launched daemon would run
  // open. Only emitted when a secret was resolved.
  const secretEntry = <REDACTED>
    ? `\n    <key>MEMWARDEN_SECRET</key><string>${xmlEscape(secret)}</string>`
    : "";
  return `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key><string>${LABEL}</string>
  <key>ProgramArguments</key>
  <array>
    <string>${xmlEscape(node)}</string>
    <string>${xmlEscape(DAEMON_ENTRY)}</string>
  </array>
  <key>EnvironmentVariables</key>
  <dict>
    <key>MEMWARDEN_DATA_DIR</key><string>${xmlEscape(dataDir)}</string>
    <key>${DAEMON_LOG_MODE_ENV}</key><string>${DAEMON_LOG_MODE_FILE}</string>${secretEntry}${tuningEnv()
      .map(([k, v]) => `\n    <key>${k}</key><string>${xmlEscape(v)}</string>`)
      .join("")}
  </dict>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key>
  <dict><key>SuccessfulExit</key><false/></dict>
  <key>StandardOutPath</key><string>${xmlEscape(log)}</string>
  <key>StandardErrorPath</key><string>${xmlEscape(log)}</string>
</dict>
</plist>
`;
}

function systemdUnit(node: string, dataDir: string, secret?: string): string {
  // Same reason as the plist: the managed daemon needs MEMWARDEN_SECRET in its
  // environment to enforce auth. Only emitted when a secret was resolved.
  const secretEnv = <REDACTED>
    ? `\nEnvironment=MEMWARDEN_SECRET=<REDACTED>
    : "";
  const tuning = tuningEnv()
    .map(([k, v]) => `\nEnvironment=${k}=${v}`)
    .join("");
  return `[Unit]
Description=memwarden memory daemon
After=network.target

[Service]
ExecStart=${node} ${DAEMON_ENTRY}
Environment=MEMWARDEN_DATA_DIR=${dataDir}
Environment=${DAEMON_LOG_MODE_ENV}=${DAEMON_LOG_MODE_JOURNALD}${secretEnv}${tuning}
Restart=on-failure
RestartSec=2

[Install]
WantedBy=default.target
`;
}

/**
 * Install + start the supervised daemon for this platform. Best-effort. When
 * `secret` is provided it is baked into the service environment so the
 * login-launched daemon enforces auth (otherwise a managed daemon would run
 * open even though the CLI generated a secret).
 */
function installServiceWithRuntime(
  dataDir: string,
  secret: <REDACTED> | undefined,
  runtime: ServiceRuntime,
): ServiceResult {
  const { home, node, platform, run } = runtime;

  // The secret and dataDir are interpolated into generated service units. A
  // newline (or, on systemd, other control chars) would let a chosen value
  // inject extra directives — e.g. `--secret $'x\nExecStartPre=/bin/evil'`
  // would add a rogue ExecStartPre that runs at login. The auto-generated
  // secret is base64url (safe), but `--secret`/`MEMWARDEN_DATA_DIR` are
  // user-controlled, so reject anything with a newline/CR/NUL up front.
  const hasControlChar = (s: string): boolean => /[\r\n\0]/.test(s);
  if (hasControlChar(dataDir) || (secret !== undefined && hasControlChar(secret))) {
    return {
      kind: platform === "darwin" ? "launchd" : "systemd",
      ok: false,
      message: "refusing to install service: secret or data dir contains a newline/control character",
    };
  }

  try {
    mkdirSync(dataDir, { recursive: true, mode: 0o700 });
  } catch {
    // non-fatal; the write below will surface a real error if the dir is bad
  }

  if (platform === "darwin") {
    const path = plistPath(home);
    try {
      // launchd opens StandardOutPath itself, so validate/create/chmod the real
      // fixed target before the plist is loaded. Failure is closed: no load.
      const log = openSecureDaemonLog(dataDir);
      log.close();
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, macPlist(node, dataDir, secret), "utf8");
      // Lock the plist down: it now carries the secret in plaintext.
      try {
        chmodSync(path, 0o600);
      } catch {
        // best-effort
      }
      try {
        run("launchctl", ["unload", path]);
      } catch {
        // not previously loaded — fine
      }
      run("launchctl", ["load", "-w", path]);
      return {
        kind: "launchd",
        ok: true,
        path,
        message: "starts at login, restarts on crash",
      };
    } catch (err) {
      return { kind: "launchd", ok: false, path, message: errMsg(err) };
    }
  }

  if (platform === "linux") {
    const path = systemdPath(home);
    try {
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, systemdUnit(node, dataDir, secret), "utf8");
      // Lock the unit down: it now carries the secret in plaintext.
      try {
        chmodSync(path, 0o600);
      } catch {
        // best-effort
      }
      run("systemctl", ["--user", "daemon-reload"]);
      run("systemctl", ["--user", "enable", "--now", "memwarden"]);
      return {
        kind: "systemd",
        ok: true,
        path,
        message: "starts at login, restarts on crash",
      };
    } catch (err) {
      return { kind: "systemd", ok: false, path, message: errMsg(err) };
    }
  }

  return {
    kind: "unsupported",
    ok: false,
    message: `no supported service manager for ${platform}`,
  };
}

/** Install using the real home, platform, executable, and service manager. */
export function installService(dataDir: string, secret?: string): ServiceResult {
  return installServiceWithRuntime(dataDir, secret, productionRuntime());
}

/** Temp-only launchd/systemd seam; never resolves the caller's real home. */
export function __installServiceForTests(
  dataDir: string,
  secret: <REDACTED> | undefined,
  testRuntime: ServiceTestRuntime,
): ServiceResult {
  return installServiceWithRuntime(dataDir, secret, {
    platform: testRuntime.platform,
    home: testRuntime.home,
    node: testRuntime.node ?? process.execPath,
    run: testRuntime.run ?? (() => undefined),
  });
}

/** Test-only generated-unit views; no filesystem or service-manager access. */
export function __macPlistForTests(
  node: string,
  dataDir: string,
  secret?: string,
): string {
  return macPlist(node, dataDir, secret);
}

export function __systemdUnitForTests(
  node: string,
  dataDir: string,
  secret?: string,
): string {
  return systemdUnit(node, dataDir, secret);
}

/** Stop + remove the supervised daemon. Best-effort. */
export function uninstallService(): ServiceResult {
  const home = homedir();
  if (process.platform === "darwin") {
    const path = plistPath(home);
    try {
      try {
        execFileSync("launchctl", ["unload", path], { stdio: "ignore" });
      } catch {
        // not loaded
      }
      rmSync(path, { force: true });
      return { kind: "launchd", ok: true, path, message: "removed" };
    } catch (err) {
      return { kind: "launchd", ok: false, path, message: errMsg(err) };
    }
  }
  if (process.platform === "linux") {
    const path = systemdPath(home);
    try {
      try {
        execFileSync("systemctl", ["--user", "disable", "--now", "memwarden"], {
          stdio: "ignore",
        });
      } catch {
        // not enabled
      }
      rmSync(path, { force: true });
      return { kind: "systemd", ok: true, path, message: "removed" };
    } catch (err) {
      return { kind: "systemd", ok: false, path, message: errMsg(err) };
    }
  }
  return {
    kind: "unsupported",
    ok: false,
    message: `no supported service manager for ${process.platform}`,
  };
}

//
// Embedding provider selection. memwarden's vector stream (and therefore
// the TurboQuant-compressed semantic memory that distinguishes it) only
// lights up when a provider is configured here.
//
//   MEMWARDEN_EMBEDDING_PROVIDER = local (default) | none
//   MEMWARDEN_EMBEDDING_MODEL    = Xenova/all-MiniLM-L6-v2 (default)
//
// "local" runs entirely on-device (see local-embedding.ts). "none" keeps
// memwarden in BM25-only mode. Cloud providers (openai, voyage) can be
// added here later behind the same interface without touching callers.

import type { EmbeddingProvider } from "../functions/types.js";
import { LocalEmbeddingProvider } from "./local-embedding.js";

export { LocalEmbeddingProvider } from "./local-embedding.js";

export function getEmbeddingProviderName(): "local" | "none" {
  const raw = (process.env.MEMWARDEN_EMBEDDING_PROVIDER ?? "local")
    .trim()
    .toLowerCase();
  return raw === "none" ? "none" : "local";
}

export function getEmbeddingModel(): string {
  const raw = process.env.MEMWARDEN_EMBEDDING_MODEL?.trim();
  return raw && raw.length > 0 ? raw : "Xenova/all-MiniLM-L6-v2";
}

/**
 * Build the configured embedding provider, or null for BM25-only mode.
 * Construction is cheap (no model load); the model loads lazily on first
 * embed, or eagerly via warmup() at boot.
 */
export function createEmbeddingProvider(): EmbeddingProvider | null {
  if (getEmbeddingProviderName() === "none") return null;
  return new LocalEmbeddingProvider(getEmbeddingModel());
}

//
// Local, in-process embedding provider. Runs a sentence-transformer
// (all-MiniLM-L6-v2, 384-dim) through transformers.js on the WASM/WebGPU
// backend — no Python, no CUDA, no native compilation, so it preserves
// memwarden's zero-native-dependency, self-custody promise. The model
// (~23MB ONNX) is downloaded once on first use and cached on disk.
//
// transformers.js is an OPTIONAL dependency, loaded lazily via a dynamic
// import with a variable specifier so the core typechecks and the test
// suite runs without it installed. If it is absent, embed() throws a clear
// message and the vector stream stays off (BM25 keeps working) — the
// guarded add path in search.ts soft-fails, it never breaks observe.

import type { EmbeddingProvider } from "../functions/types.js";
import { importTransformers } from "./runtime.js";

const DEFAULT_MODEL = "Xenova/all-MiniLM-L6-v2";
const MINILM_DIMS = 384;

// Known output dimensions for the models we ship as presets. Anything else
// is probed from the first embedding.
const KNOWN_DIMS: Record<string, number> = {
  "Xenova/all-MiniLM-L6-v2": 384,
  "Xenova/bge-small-en-v1.5": 384,
  "Xenova/nomic-embed-text-v1": 768,
};

// Minimal shape of the transformers.js pipeline we rely on.
type FeatureOutput = {
  tolist: () => number[][];
  dispose?: () => void;
};

type FeatureExtractor = ((
  input: string | string[],
  opts: { pooling: "mean"; normalize: boolean },
) => Promise<FeatureOutput>) & {
  dispose?: () => Promise<void>;
};

export class LocalEmbeddingProvider implements EmbeddingProvider {
  readonly name: string;
  readonly dimensions: number;
  private model: string;
  private extractor: FeatureExtractor | null = null;
  private loading: Promise<FeatureExtractor> | null = null;
  private disposing = false;

  constructor(model: string = DEFAULT_MODEL) {
    this.model = model;
    this.name = `local:${model}`;
    this.dimensions = KNOWN_DIMS[model] ?? MINILM_DIMS;
  }

  // Lazily construct the feature-extraction pipeline. The import uses a
  // variable specifier on purpose: it keeps tsc from resolving the optional
  // package at build time and isolates the heavy load to first use.
  private async ensure(): Promise<FeatureExtractor> {
    if (this.disposing) throw new Error("embedding provider is shutting down");
    if (this.extractor) return this.extractor;
    if (!this.loading) {
      this.loading = (async () => {
        // Resolution chain: bare specifier, then <dataDir>/runtime (where
        // `memwarden up` installs it). Throws actionably when neither hits.
        const mod = await importTransformers();
        const pipeline = mod.pipeline as
          | ((
              task: string,
              model: string,
              opts?: { dtype?: string },
            ) => Promise<FeatureExtractor>)
          | undefined;
        if (typeof pipeline !== "function") {
          throw new Error(
            "@huggingface/transformers did not export a usable 'pipeline'",
          );
        }
        // fp16 by default: recall measured identical to fp32 on the recall
        // benchmark while cutting the always-on daemon from ~386MB to ~300MB
        // RSS. MEMWARDEN_EMBED_DTYPE=q8 goes to ~246MB at a small measured
        // recall cost (~7pts R@10 on the benchmark); =fp32 restores the old
        // default. The benchmark runs this same default — rerun it after
        // changing this.
        const dtype = process.env.MEMWARDEN_EMBED_DTYPE?.trim() || "fp16";
        const extractor = await pipeline("feature-extraction", this.model, {
          dtype,
        });
        this.extractor = extractor;
        return extractor;
      })();
    }
    return this.loading;
  }

  /** Warm the model so the first observe/search doesn't pay the load. */
  async warmup(): Promise<void> {
    await this.ensure();
  }

  /**
   * Fast check: is transformers.js resolvable anywhere on the chain (bare
   * specifier or the memwarden runtime dir)? Resolves the module (cheap)
   * without building the pipeline or downloading the model (expensive).
   * Lets the daemon decide at boot whether to advertise semantic memory at
   * all, instead of claiming it's on and silently falling back to BM25.
   */
  static async isAvailable(): Promise<boolean> {
    try {
      const mod = await importTransformers();
      return typeof mod.pipeline === "function";
    } catch {
      return false;
    }
  }

  async embed(text: string): Promise<Float32Array> {
    const extractor = await this.ensure();
    const out = await extractor(text, { pooling: "mean", normalize: true });
    try {
      const row = out.tolist()[0];
      if (!row) throw new Error("embedding extraction returned no rows");
      return Float32Array.from(row);
    } finally {
      out.dispose?.();
    }
  }

  async embedBatch(texts: string[]): Promise<Float32Array[]> {
    if (texts.length === 0) return [];
    const extractor = await this.ensure();
    const out = await extractor(texts, { pooling: "mean", normalize: true });
    try {
      return out.tolist().map((row) => Float32Array.from(row));
    } finally {
      out.dispose?.();
    }
  }

  /** Dispose ONNX sessions before Node tears down native runtime mutexes. */
  async dispose(): Promise<void> {
    if (this.disposing) return;
    this.disposing = true;
    const extractor =
      this.extractor ?? (this.loading ? await this.loading.catch(() => null) : null);
    this.extractor = null;
    this.loading = null;
    if (extractor?.dispose) await extractor.dispose();
  }
}

//
// Project identity: a stable key for "the same project" that survives git
// worktrees, clones at different paths, and moved checkouts. Path scoping
// (paths.ts) treats /repo and /repo-worktree-b as unrelated even when they
// are the same repository — the memory looks gone, the worst failure mode.
//
// The key is derived, in order of preference:
//   1. the normalized git remote URL (origin first)   -> "git:github.com/u/r"
//   2. a remote-less repo: its MAIN repository root   -> "gitroot:/abs/main"
//      (worktrees resolve `.git` files to the main .git dir, so every
//       worktree of one repo shares the key)
//   3. not a repo at all: null — callers fall back to the canonical path.
//
// ADDITIVE ONLY: the key is stored alongside (never instead of) the existing
// project/cwd path fields, and recall uses it only to WIDEN path scoping —
// data without a key keeps matching exactly as before.
//
// No child processes: hooks fire on every tool call, so this reads .git
// files directly (cheap, no `git` binary dependency) and memoizes per cwd.

import { existsSync, readFileSync, statSync } from "node:fs";
import { dirname, isAbsolute, join, resolve } from "node:path";
import { canonicalizePath } from "./paths.js";

/**
 * Normalize a git remote URL to `host/path`, lowercased, credentials and the
 * `.git` suffix stripped. Handles the two forms git itself writes: scp-like
 * (`git@host:path`) and protocol URLs (`ssh://`, `https://`, `git://`).
 * Returns null for anything else (file remotes, relative paths) — those are
 * machine-local and no better than the repo-root fallback.
 */
export function normalizeGitRemote(url: string): string | null {
  const trimmed = url.trim();
  if (!trimmed) return null;
  let host: string;
  let path: string;
  const proto = /^(?:https?|ssh|git):\/\/(?:[^@/]+@)?([^/]+)\/(.+)$/i.exec(trimmed);
  const scp = /^(?:[^@/]+@)?([^:/]+\.[^:/]+):(?!\/\/)(.+)$/.exec(trimmed);
  if (proto) {
    host = proto[1]!;
    path = proto[2]!;
  } else if (scp) {
    host = scp[1]!;
    path = scp[2]!;
  } else {
    return null;
  }
  host = host.replace(/:\d+$/, ""); // port is transport detail, not identity
  path = path.replace(/\.git\/?$/, "").replace(/\/+$/, "").replace(/^\/+/, "");
  if (!host || !path) return null;
  return `${host}/${path}`.toLowerCase();
}

/** Walk up from `startDir` to the nearest directory containing `.git`. */
function findGitEntry(startDir: string): { root: string; entry: string } | null {
  let dir = resolve(startDir);
  for (;;) {
    const entry = join(dir, ".git");
    if (existsSync(entry)) return { root: dir, entry };
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

const worktreeRootCache = new Map<string, { root: string | null; at: number }>();
// A directory that is not in git yet may become one (`git init`): negative
// answers are only trusted briefly.
const NEGATIVE_TTL_MS = 60_000;

/**
 * The checkout root (the directory holding `.git`) that contains `dir`, or
 * null outside a git checkout. Cached: recall asks for it per classified
 * memory. Relative evidence paths are anchored here, not at whichever
 * subdirectory a session happened to start in.
 */
export function gitWorktreeRoot(dir: string): string | null {
  const key = resolve(dir);
  const hit = worktreeRootCache.get(key);
  if (hit && (hit.root !== null || Date.now() - hit.at < NEGATIVE_TTL_MS)) return hit.root;
  const root = findGitEntry(key)?.root ?? null;
  if (worktreeRootCache.size > 1024) worktreeRootCache.clear();
  worktreeRootCache.set(key, { root, at: Date.now() });
  return root;
}

/**
 * Resolve the MAIN .git directory, following a worktree's `.git` file
 * (`gitdir: <main>/.git/worktrees/<name>`) back to `<main>/.git` so all
 * worktrees of one repository resolve to the same place.
 */
function mainGitDir(root: string, entry: string): string | null {
  try {
    if (statSync(entry).isDirectory()) return entry;
    const content = readFileSync(entry, "utf8");
    const m = /^gitdir:\s*(.+)\s*$/m.exec(content);
    if (!m) return null;
    const pointed = isAbsolute(m[1]!) ? m[1]! : resolve(root, m[1]!);
    const wt = /^(.*[\\/]\.git)[\\/]worktrees[\\/][^\\/]+[\\/]?$/.exec(pointed);
    return wt ? wt[1]! : pointed;
  } catch {
    return null;
  }
}

/**
 * Extract the `origin` remote URL (or, failing that, the first remote) from
 * git config text. Line-oriented on purpose: enough for the exact
 * `[remote "x"]` / `url = …` shape git writes, with no INI parser dependency.
 */
export function remoteUrlFromConfig(config: string): string | null {
  let section: string | null = null;
  let firstUrl: string | null = null;
  for (const line of config.split("\n")) {
    const header = /^\s*\[remote\s+"([^"]+)"\]\s*$/.exec(line);
    if (header) {
      section = header[1]!;
      continue;
    }
    if (/^\s*\[/.test(line)) {
      section = null;
      continue;
    }
    if (!section) continue;
    const url = /^\s*url\s*=\s*(.+?)\s*$/.exec(line);
    if (!url) continue;
    if (section === "origin") return url[1]!;
    if (firstUrl === null) firstUrl = url[1]!;
  }
  return firstUrl;
}

// Hooks call this on every tool event; the answer for a directory is stable
// for the life of a daemon/CLI process, so memoize per cwd.
const keyCache = new Map<string, string | null>();

/**
 * The git-derived project key for a directory, or null when it is not inside
 * a git repository (callers fall back to the canonical path).
 */
export function gitProjectKey(cwd: string): string | null {
  const dir = (cwd ?? "").trim();
  if (!dir || !isAbsolute(dir)) return null;
  const hit = keyCache.get(dir);
  if (hit !== undefined) return hit;
  let key: string | null = null;
  try {
    const found = findGitEntry(dir);
    if (found) {
      const gitDir = mainGitDir(found.root, found.entry);
      if (gitDir) {
        const configPath = join(gitDir, "config");
        const remote = existsSync(configPath)
          ? remoteUrlFromConfig(readFileSync(configPath, "utf8"))
          : null;
        const normalized = remote ? normalizeGitRemote(remote) : null;
        key = normalized
          ? `git:${normalized}`
          : `gitroot:${canonicalizePath(dirname(gitDir))}`;
      }
    }
  } catch {
    key = null;
  }
  keyCache.set(dir, key);
  return key;
}

/**
 * The stable project key for a directory: git identity when available,
 * canonical path otherwise. Never empty for a non-empty input.
 */
export function projectKey(cwd: string): string {
  return gitProjectKey(cwd) ?? canonicalizePath(cwd);
}

/** Test hook: drop the memo (temp repos are created and deleted per test). */
export function __resetGitIdentityCache(): void {
  worktreeRootCache.clear();
  keyCache.clear();
}

//
// Memory project identity.
//
// A filesystem path and a stable git-derived project key answer different
// questions: the key decides whether two checkouts belong to the same project;
// the path decides which checkout's files must be read.  Keep both all the way
// through distilled-memory lookup and verification.  The helpers here are also
// the single compatibility boundary for legacy Memory rows whose overloaded
// `project` field may contain either kind of value.
//

import type { StateKV } from "../state/kv.js";
import { KV } from "../state/schema.js";
import { projectKey as computeProjectKey } from "./git-identity.js";
import { canonicalizePath } from "./paths.js";
import { isMemoryRecallable } from "./memory-utils.js";
import type { Memory, Session } from "./types.js";

export interface ProjectIdentity {
  /** Capture-time project filesystem path (normally the repository root). */
  projectPath?: string;
  /** Stable git-derived identity, or the canonical path fallback. */
  projectKey?: string;
  /** Capture-time working directory used to interpret relative evidence. */
  captureCwd?: string;
}

export interface ResolvedMemoryIdentity extends ProjectIdentity {
  /** Best source session for legacy metadata and explanation output. */
  sourceSession?: Session;
}

/** Minimal structural shape accepted by the resolver (Canon inventory uses a
 * projection rather than the complete persisted Memory interface). */
export interface MemoryIdentityRecord {
  sessionIds?: string[];
  projectPath?: string;
  projectKey?: string;
  captureCwd?: string;
  project?: string;
  provenance?: { cwd?: string };
}

function nonEmpty(value: unknown): string | undefined {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : undefined;
}

/** Legacy consolidation wrote stable git keys into Memory.project. */
export function isStableProjectKey(value: string | undefined): boolean {
  return value?.startsWith("git:") === true || value?.startsWith("gitroot:") === true;
}

function samePath(a: string | undefined, b: string | undefined): boolean {
  return !!a && !!b && canonicalizePath(a) === canonicalizePath(b);
}

/** Resolve a Session into the same split identity shape used by Memory. */
export function sessionProjectIdentity(session: Session): ProjectIdentity {
  const projectPath = nonEmpty(session.project);
  const captureCwd = nonEmpty(session.cwd);
  // Old sessions predate Session.projectKey.  When their checkout still
  // exists, derive it now so their distilled memories can move with a remote
  // or linked worktree too.  computeProjectKey falls back to the canonical
  // path, so this remains additive for non-git sessions.
  const projectKey =
    nonEmpty(session.projectKey) ??
    (captureCwd ? computeProjectKey(captureCwd) : undefined);
  return {
    ...(projectPath ? { projectPath } : {}),
    ...(projectKey ? { projectKey } : {}),
    ...(captureCwd ? { captureCwd } : {}),
  };
}

/**
 * Split a Memory's identity, consulting its source sessions when fields are
 * absent.  Explicit new fields always win.  Legacy `project` values beginning
 * `git:`/`gitroot:` are keys; other values remain filesystem/project paths.
 * A source session can disambiguate custom historical keys as well.
 */
export function resolveMemoryIdentity(
  memory: MemoryIdentityRecord,
  sessionsById: ReadonlyMap<string, Session> = new Map(),
): ResolvedMemoryIdentity {
  const sourceSessions = (memory.sessionIds ?? [])
    .map((id) => sessionsById.get(id))
    .filter((session): session is Session => session !== undefined);
  const recordedCaptureCwd =
    nonEmpty(memory.captureCwd) ?? nonEmpty(memory.provenance?.cwd);
  const explicitKey = nonEmpty(memory.projectKey);
  const legacyProject = nonEmpty(memory.project);

  let sourceSession = sourceSessions.find((session) =>
    samePath(nonEmpty(session.cwd), recordedCaptureCwd),
  );
  if (!sourceSession && explicitKey) {
    sourceSession = sourceSessions.find(
      (session) => sessionProjectIdentity(session).projectKey === explicitKey,
    );
  }
  if (!sourceSession && legacyProject) {
    sourceSession = sourceSessions.find((session) => {
      const identity = sessionProjectIdentity(session);
      return (
        identity.projectKey === legacyProject ||
        samePath(identity.projectPath, legacyProject) ||
        samePath(identity.captureCwd, legacyProject)
      );
    });
  }
  sourceSession ??= sourceSessions[0];

  const sourceIdentity = sourceSession
    ? sessionProjectIdentity(sourceSession)
    : undefined;
  // Besides the two known prefixes, a source session can prove that a custom
  // legacy value was its key rather than its path.
  const legacyIsKey =
    isStableProjectKey(legacyProject) ||
    sourceSessions.some(
      (session) => sessionProjectIdentity(session).projectKey === legacyProject,
    );
  const projectPath =
    nonEmpty(memory.projectPath) ??
    (!legacyIsKey ? legacyProject : undefined) ??
    sourceIdentity?.projectPath;
  const projectKey =
    explicitKey ??
    (legacyIsKey ? legacyProject : undefined) ??
    sourceIdentity?.projectKey;
  const captureCwd = recordedCaptureCwd ?? sourceIdentity?.captureCwd;

  return {
    ...(projectPath ? { projectPath } : {}),
    ...(projectKey ? { projectKey } : {}),
    ...(captureCwd ? { captureCwd } : {}),
    ...(sourceSession ? { sourceSession } : {}),
  };
}

export function hasProjectIdentity(identity: ProjectIdentity): boolean {
  return !!(identity.projectKey || identity.projectPath || identity.captureCwd);
}

/**
 * Does this captured identity belong to `path`?  Stable identity widens the
 * match across worktrees/clones; path comparison preserves legacy exact-scope
 * behavior.  This function only answers identity.  Verification callers must
 * still pass the actual caller path to classifyProvenance — never the key.
 */
export function projectIdentityMatchesPath(
  identity: ProjectIdentity,
  path: string,
): boolean {
  const target = nonEmpty(path);
  if (!target) return false;
  const targetKey = computeProjectKey(target);
  if (identity.projectKey && identity.projectKey === targetKey) return true;
  const targetPath = canonicalizePath(target);
  return [identity.projectPath, identity.captureCwd].some(
    (candidate) =>
      candidate !== undefined && canonicalizePath(candidate) === targetPath,
  );
}

/** Add the split fields to a legacy row without removing its readable alias. */
export function migrateLegacyMemoryIdentity(
  memory: Memory,
  sessionsById: ReadonlyMap<string, Session> = new Map(),
): Memory {
  const identity = resolveMemoryIdentity(memory, sessionsById);
  return {
    ...memory,
    ...(identity.projectPath ? { projectPath: identity.projectPath } : {}),
    ...(identity.projectKey ? { projectKey: identity.projectKey } : {}),
    ...(identity.captureCwd ? { captureCwd: identity.captureCwd } : {}),
  };
}

/**
 * Canon/export inventory with the same scoping semantics as safe recall and
 * doctor. A scoped inventory fails closed for identity-less rows; legacy rows
 * carrying only `project` are resolved explicitly above and remain readable.
 */
export async function listMemoryInventory(
  kv: StateKV,
  projectPath?: string,
): Promise<Memory[]> {
  const [memories, sessions] = await Promise.all([
    kv.list<Memory>(KV.memories).catch(() => [] as Memory[]),
    kv.list<Session>(KV.sessions).catch(() => [] as Session[]),
  ]);
  const sessionsById = new Map(sessions.map((session) => [session.id, session]));
  const scoped = nonEmpty(projectPath);
  const out: Memory[] = [];
  for (const memory of memories) {
    if (!isMemoryRecallable(memory)) continue;
    const identity = resolveMemoryIdentity(memory, sessionsById);
    if (
      scoped &&
      (!hasProjectIdentity(identity) ||
        !projectIdentityMatchesPath(identity, scoped))
    ) {
      continue;
    }
    out.push(migrateLegacyMemoryIdentity(memory, sessionsById));
  }
  return out;
}

#!/usr/bin/env node
//
// memwarden MCP server entrypoint. Speaks JSON-RPC over stdio and proxies
// to a running memwarden daemon. Point any MCP client at this:
//
//   { "command": "npx", "args": ["-y", "@memwarden/mcp"],
//     "env": { "MEMWARDEN_URL": "http://localhost:3111" } }

import { createMcpServer, runStdio } from "./server.js";
import { ensureDaemon } from "../daemon/ensure.js";
import { getSecret } from "../functions/config.js";

const baseUrl = process.env.MEMWARDEN_URL ?? "http://localhost:3111";
// Resolve env first, then the persisted <dataDir>/secret file, so a server
// launched without the env var still authenticates to a secured daemon.
const secret = <REDACTED>

// Self-heal: revive the daemon on demand if a request finds it down.
const ensureUp = async (): Promise<void> => {
  await ensureDaemon(baseUrl);
};

const server = createMcpServer({
  baseUrl,
  ensureUp,
  ...(secret ? { secret } : {}),
});

// Warm the daemon at startup so the first recall is instant, but never block
// the stdio handshake on it.
void ensureDaemon(baseUrl).catch(() => undefined);

runStdio(server);

//
// In-process observability for memwarden. Tracks the two numbers that
// decide whether this layer is actually good for an agent:
//
//   1. Token economy — how many tokens we save by storing compressed
//      observations and serving budgeted context instead of raw history.
//   2. Latency — how fast search and context return, so switching agents
//      never means "wait while it finds the context."
//
// Running aggregates, no I/O on the hot path. Latency keeps a bounded
// sample window for percentiles. Reset for tests. Durable persistence
// (a cost-ledger KV table) can layer on top later without changing callers.

const MAX_SAMPLES = 1000;

function estimateTokens(text: string): number {
  // Same heuristic the context packer uses (~3 chars/token). Centralized
  // here so every token number in the system comes from one place.
  return Math.ceil(text.length / 3);
}

function percentile(sorted: number[], p: number): number {
  if (sorted.length === 0) return 0;
  const idx = Math.min(
    sorted.length - 1,
    Math.max(0, Math.ceil((p / 100) * sorted.length) - 1),
  );
  return sorted[idx] as number;
}

class Metrics {
  private observeCount = 0;
  private observeRawTokens = <REDACTED>
  private observeStoredTokens = <REDACTED>

  private contextCount = 0;
  private contextCandidateTokens = <REDACTED>
  private contextServedTokens = <REDACTED>
  private contextLatency: number[] = [];

  private searchCount = 0;
  private searchLatency: number[] = [];

  private pushSample(arr: number[], v: number): void {
    arr.push(v);
    if (arr.length > MAX_SAMPLES) arr.shift();
  }

  /** Record one observe: raw payload size vs the compressed record stored. */
  recordObserve(rawText: string, storedText: string): void {
    this.observeCount++;
    this.observeRawTokens += estimateTokens(rawText);
    this.observeStoredTokens += estimateTokens(storedText);
  }

  /**
   * Record one context build: candidate = tokens of everything that
   * matched, served = tokens actually returned under budget.
   */
  recordContext(
    candidateTokens: <REDACTED>
    servedTokens: <REDACTED>
    latencyMs: number,
  ): void {
    this.contextCount++;
    this.contextCandidateTokens += candidateTokens;
    this.contextServedTokens += servedTokens;
    this.pushSample(this.contextLatency, latencyMs);
  }

  recordSearch(latencyMs: number): void {
    this.searchCount++;
    this.pushSample(this.searchLatency, latencyMs);
  }

  snapshot(): Record<string, unknown> {
    const ctxSorted = [...this.contextLatency].sort((a, b) => a - b);
    const searchSorted = [...this.searchLatency].sort((a, b) => a - b);
    const pct = (saved: number, total: number) =>
      total > 0 ? Math.round((saved / total) * 1000) / 10 : 0;

    return {
      observe: {
        count: this.observeCount,
        rawTokens: <REDACTED>
        storedTokens: <REDACTED>
        reductionPct: pct(
          this.observeRawTokens - this.observeStoredTokens,
          this.observeRawTokens,
        ),
      },
      context: {
        count: this.contextCount,
        candidateTokens: <REDACTED>
        servedTokens: <REDACTED>
        reductionPct: pct(
          this.contextCandidateTokens - this.contextServedTokens,
          this.contextCandidateTokens,
        ),
        latencyMs: {
          p50: Math.round(percentile(ctxSorted, 50)),
          p95: Math.round(percentile(ctxSorted, 95)),
        },
      },
      search: {
        count: this.searchCount,
        latencyMs: {
          p50: Math.round(percentile(searchSorted, 50)),
          p95: Math.round(percentile(searchSorted, 95)),
        },
      },
    };
  }

  reset(): void {
    this.observeCount = 0;
    this.observeRawTokens = <REDACTED>
    this.observeStoredTokens = <REDACTED>
    this.contextCount = 0;
    this.contextCandidateTokens = <REDACTED>
    this.contextServedTokens = <REDACTED>
    this.contextLatency = [];
    this.searchCount = 0;
    this.searchLatency = [];
  }
}

/** Process-wide metrics singleton. */
export const metrics = new Metrics();
export { estimateTokens };

//
// The memory proxy: an OpenAI-compatible gateway that turns memwarden into
// a universal, automatic memory layer for every tool that speaks the
// /v1/chat/completions protocol — local models (Ollama :11434/v1, LM Studio
// :1234/v1) and paid ones (OpenAI, OpenRouter, Together) alike. They all
// share that one boundary, and the proxy is blind to which is behind it, so
// it is a single memory layer for all of them.
//
// On a chat completion the proxy:
//   1. pulls the latest user turn as a query,
//   2. asks the local daemon for relevant memory (/memwarden/search,
//      narrative format),
//   3. injects it into the first USER message, delimited and framed as
//      untrusted data (never a system message — recalled memory can embed
//      hostile captured text and must not get instruction-level authority),
//   4. forwards the rewritten request to the configured upstream,
//   5. streams the response straight back to the client unchanged while
//      tee-ing it to reconstruct the assistant's answer,
//   6. captures the user turn + answer into memory (/memwarden/observe).
//
// Everything else (GET /v1/models, etc.) is a transparent passthrough — no
// injection, no capture. The kernel's own HTTP server JSON-buffers every
// response and cannot stream, which is why the proxy is a separate node:http
// server doing raw request/response piping.

import {
  createServer,
  request as httpRequest,
  type IncomingMessage,
  type Server,
  type ServerResponse,
} from "node:http";
import { request as httpsRequest } from "node:https";
import { frameMemoryBlock } from "../functions/injection-format.js";
import { createHash } from "node:crypto";
import { URL } from "node:url";
import { canonicalizePath } from "../functions/paths.js";
import { isLoopbackHost } from "../kernel/http.js";
import { timingSafeCompare } from "../triggers/auth.js";
import {
  isCaptureEnabled,
  isInjectEnabled,
  isProjectExcluded,
} from "../functions/config.js";

export interface ProxyOptions {
  /** Port to listen on. */
  port: number;
  host?: string;
  /** Upstream OpenAI-compatible base URL, e.g. https://api.openai.com/v1. */
  upstreamUrl: string;
  /** API key forwarded to the upstream as Authorization: Bearer. */
  upstreamKey?: string;
  /** Local memwarden daemon base, e.g. http://127.0.0.1:3111. */
  daemonUrl: string;
  /**
   * The install's shared secret. Used outbound for the daemon's auth'd
   * routes, and enforced inbound: when set, proxy clients must present it as
   * `Authorization: Bearer <secret>` (set the tool's API key to it).
   */
  secret?: string;
  /** Project/workspace this proxy's captures belong to (defaults to cwd). */
  project: string;
  /** Working directory used to scope recall. */
  cwd: string;
  /** Token budget for injected memory. */
  tokenBudget?: number;
}

export interface RunningProxy {
  server: Server;
  port: number;
  close(): Promise<void>;
}

interface Ctx extends ProxyOptions {
  sessionId: string;
}

// Hop-by-hop headers must not be forwarded across a proxy boundary.
const HOP_BY_HOP = new Set([
  "connection",
  "keep-alive",
  "proxy-authenticate",
  "proxy-authorization",
  "te",
  "trailer",
  "transfer-encoding",
  "upgrade",
  "content-length",
  "host",
]);

export function startProxyServer(opts: ProxyOptions): RunningProxy {
  const host = opts.host ?? "127.0.0.1";
  // One session per proxy process, scoped to the project it serves. Turns
  // from different conversations share it; the daemon's dedup keys on the
  // prompt so distinct prompts still land. The project hash matters: a
  // session's project metadata is fixed at creation, so a bare
  // `proxy-<port>` session created while serving project A would swallow a
  // later proxy's project-B captures and make them unsearchable from B.
  const projectHash = createHash("sha256")
    .update(canonicalizePath(opts.project))
    .digest("hex")
    .slice(0, 12);
  const ctx: Ctx = { ...opts, sessionId: `proxy-${opts.port}-${projectHash}` };

  const server = createServer((req, res) => {
    handle(req, res, ctx).catch((err) => {
      if (!res.headersSent) {
        res.statusCode = 502;
        res.setHeader("content-type", "application/json");
        res.end(
          JSON.stringify({
            error: "memwarden_proxy_error",
            message: err instanceof Error ? err.message : String(err),
          }),
        );
      } else if (!res.writableEnded) {
        res.end();
      }
    });
  });

  server.listen(opts.port, host);
  return {
    server,
    port: opts.port,
    close: () =>
      new Promise<void>((resolve) => server.close(() => resolve())),
  };
}

async function handle(
  req: IncomingMessage,
  res: ServerResponse,
  ctx: Ctx,
): Promise<void> {
  // Same DNS-rebinding firewall as the kernel HTTP server: the proxy is a
  // localhost-only gateway that spends the upstream API key, so a webpage that
  // rebinds DNS to 127.0.0.1 must not reach it. The Host header reflects the
  // hostname the client actually targeted; reject anything non-loopback.
  if (!isLoopbackHost(req.headers.host, req.socket.localPort)) {
    res.statusCode = 403;
    res.setHeader("content-type", "application/json");
    res.end(JSON.stringify({ error: "forbidden_host" }));
    return;
  }

  const url = new URL(req.url ?? "/", "http://localhost");
  const path = url.pathname;

  if (req.method === "GET" && path === "/livez") {
    res.statusCode = 200;
    res.setHeader("content-type", "application/json");
    res.end(JSON.stringify({ status: "ok", service: "memwarden-proxy" }));
    return;
  }

  // Client auth: when the install has a secret, the proxy requires it too.
  // The proxy substitutes the real upstream API key and writes captures into
  // memory, so an open localhost port would let any local process spend the
  // key and poison capture. OpenAI-compatible tools already send their
  // configured API key as `Authorization: Bearer` — set that key to the
  // memwarden secret. buildUpstreamHeaders strips the client Authorization
  // before forwarding, so the secret never reaches the upstream. /livez
  // stays open: it spends no key and captures nothing.
  if (ctx.secret) {
    const auth = req.headers.authorization;
    if (
      typeof auth !== "string" ||
      !timingSafeCompare(auth, `Bearer ${ctx.secret}`)
    ) {
      res.statusCode = 401;
      res.setHeader("content-type", "application/json");
      res.end(
        JSON.stringify({
          error: "unauthorized",
          message:
            "Set your tool's API key to the memwarden secret (the `secret` file in your data dir)",
        }),
      );
      return;
    }
  }

  const isChat =
    req.method === "POST" &&
    (path === "/v1/chat/completions" || path === "/chat/completions");

  const reqBody = await readBody(req);

  // For a chat completion, inject memory and remember the query so we can
  // capture the answer. Other paths pass straight through.
  // The same switches the hooks honor: MEMWARDEN_INJECT / MEMWARDEN_CAPTURE
  // and the per-project exclude list, checked per request so `memwarden
  // exclude` takes effect without a daemon restart.
  const excluded = isProjectExcluded(ctx.cwd);
  const inject = isInjectEnabled() && !excluded;
  const capture = isCaptureEnabled() && !excluded;

  let outBody = reqBody;
  let query = "";
  if (isChat && reqBody.length && (inject || capture)) {
    try {
      const payload = JSON.parse(reqBody.toString("utf8")) as ChatRequest;
      query = extractUserQuery(payload);
      if (query && inject) {
        const memory = await fetchMemory(ctx, query).catch(() => "");
        if (memory) {
          outBody = Buffer.from(
            JSON.stringify(injectMemory(payload, memory)),
            "utf8",
          );
        }
      }
    } catch {
      // Not JSON we understand — forward the original bytes untouched.
    }
  }

  const target = new URL(ctx.upstreamUrl + path.replace(/^\/v1/, ""));
  const upstream = await requestUpstream(
    target,
    req.method ?? "GET",
    buildUpstreamHeaders(req.headers, outBody, ctx.upstreamKey),
    outBody.length ? outBody : undefined,
  );

  res.statusCode = upstream.statusCode ?? 502;
  for (const [k, v] of Object.entries(upstream.headers)) {
    if (v === undefined || HOP_BY_HOP.has(k.toLowerCase())) continue;
    res.setHeader(k, v as string | string[]);
  }

  // Pipe the response straight back, tee-ing it so we can reconstruct the
  // assistant's answer for capture once the stream finishes. Robust to the
  // client disconnecting mid-stream: writing to a dead socket throws, and
  // because handle()'s promise has already resolved by now, that throw would
  // be an unhandled exception that can take the daemon down. So we guard the
  // write, stop tee-ing and abort the upstream the moment the client goes
  // away, honor backpressure, and cap the capture buffer (a huge or hostile
  // upstream response must not balloon memory — http.ts caps request bodies;
  // this caps the response we buffer for capture).
  const captured: Buffer[] = [];
  let capturedBytes = 0;
  let captureOverflow = false;
  const MAX_CAPTURE_BYTES = 4 * 1024 * 1024;
  const wantCapture = isChat && query !== "" && capture;
  let done = false;

  const stopUpstream = (): void => {
    if (done) return;
    done = true;
    upstream.destroy();
  };

  upstream.on("data", (chunk: Buffer) => {
    if (done) return;
    if (wantCapture && !captureOverflow) {
      capturedBytes += chunk.length;
      if (capturedBytes > MAX_CAPTURE_BYTES) {
        captureOverflow = true; // stop buffering; still stream to the client
        captured.length = 0;
      } else {
        captured.push(chunk);
      }
    }
    let ok = false;
    try {
      ok = res.write(chunk);
    } catch {
      stopUpstream();
      return;
    }
    if (!ok) {
      // client can't keep up — pause until it drains
      upstream.pause();
      res.once("drain", () => {
        if (!done) upstream.resume();
      });
    }
  });
  upstream.on("end", () => {
    if (done) return;
    done = true;
    if (!res.writableEnded) res.end();
    if (wantCapture && !captureOverflow && (upstream.statusCode ?? 0) < 400) {
      const answer = extractAnswer(
        Buffer.concat(captured),
        upstream.headers["content-type"],
      );
      if (answer) void captureExchange(ctx, query, answer);
    }
  });
  upstream.on("error", () => {
    done = true;
    if (!res.writableEnded) res.end();
  });
  // Client hung up (tab closed, request aborted): stop pulling from upstream
  // and tee-ing into a socket that no longer exists.
  res.on("close", stopUpstream);
  res.on("error", stopUpstream);
}

// --- request/response plumbing -------------------------------------

function readBody(req: IncomingMessage): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => chunks.push(c));
    req.on("end", () => resolve(Buffer.concat(chunks)));
    req.on("error", reject);
  });
}

function buildUpstreamHeaders(
  incoming: IncomingMessage["headers"],
  body: Buffer,
  upstreamKey: string | undefined,
): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(incoming)) {
    const lower = k.toLowerCase();
    if (v === undefined || HOP_BY_HOP.has(lower)) continue;
    if (lower === "authorization") continue; // overridden below
    if (lower === "accept-encoding") continue; // forced to identity below
    out[k] = Array.isArray(v) ? v.join(", ") : v;
  }
  // Identity encoding so the tee can parse the answer without gunzipping.
  out["accept-encoding"] = "identity";
  if (body.length) out["content-length"] = String(body.length);
  // The client's key (if any) is replaced with the configured upstream key;
  // a local model that needs none simply gets no Authorization header.
  if (upstreamKey) out["authorization"] = `Bearer ${upstreamKey}`;
  return out;
}

function requestUpstream(
  target: URL,
  method: string,
  headers: Record<string, string>,
  body: Buffer | undefined,
): Promise<IncomingMessage> {
  return new Promise((resolve, reject) => {
    const isHttps = target.protocol === "https:";
    const send = isHttps ? httpsRequest : httpRequest;
    const req = send(
      {
        protocol: target.protocol,
        hostname: target.hostname,
        port: target.port || (isHttps ? 443 : 80),
        path: target.pathname + target.search,
        method,
        headers,
      },
      (res) => resolve(res),
    );
    req.on("error", reject);
    if (body) req.write(body);
    req.end();
  });
}

// --- chat shape + memory injection ---------------------------------

interface ChatMessage {
  role: string;
  content: string | Array<{ type?: string; text?: string }>;
}
interface ChatRequest {
  messages?: ChatMessage[];
  [k: string]: unknown;
}

function messageText(content: ChatMessage["content"]): string {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content
      .map((p) => (typeof p?.text === "string" ? p.text : ""))
      .filter(Boolean)
      .join("\n");
  }
  return "";
}

function extractUserQuery(payload: ChatRequest): string {
  const messages = Array.isArray(payload.messages) ? payload.messages : [];
  for (let i = messages.length - 1; i >= 0; i--) {
    const m = messages[i];
    if (m && m.role === "user") return messageText(m.content).trim();
  }
  return "";
}

// Recalled memory is DATA, not instructions: it may embed hostile text
// captured from tool output or a repository (persistent prompt injection,
// OWASP ASI06). So it must never ride in a `system` message — that would
// hand captured text instruction-level authority. The block comes from the
// SHARED formatter so this surface gets the same delimiter-forgery defense
// as the SessionStart hook (an embedded "</memwarden-memory>" is defanged,
// never able to close the block).
const frameMemory = frameMemoryBlock;

function injectMemory(payload: ChatRequest, memory: string): ChatRequest {
  const messages = Array.isArray(payload.messages)
    ? payload.messages.slice()
    : [];
  const framed = frameMemory(memory);
  // Prepend to the first user message so the request keeps a valid
  // role sequence for strict OpenAI-compatible upstreams (no doubled user
  // turns, developer system prompt untouched and still first).
  const at = messages.findIndex((m) => m?.role === "user");
  if (at >= 0) {
    const m = messages[at]!;
    if (typeof m.content === "string") {
      messages[at] = { ...m, content: framed + "\n\n" + m.content };
    } else if (Array.isArray(m.content)) {
      messages[at] = {
        ...m,
        content: [{ type: "text", text: framed + "\n\n" }, ...m.content],
      };
    }
  } else {
    // No user turn (shouldn't happen: the recall query came from one).
    // Fall back to a standalone user-role preamble after any leading
    // system messages — still never a system message.
    let i = 0;
    while (i < messages.length && messages[i]?.role === "system") i++;
    messages.splice(i, 0, { role: "user", content: framed });
  }
  return { ...payload, messages };
}

function extractAnswer(buf: Buffer, contentType: unknown): string {
  const text = buf.toString("utf8");
  const ct = typeof contentType === "string" ? contentType : "";
  if (ct.includes("text/event-stream") || text.startsWith("data:")) {
    let acc = "";
    for (const line of text.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed.startsWith("data:")) continue;
      const data = trimmed.slice(5).trim();
      if (!data || data === "[DONE]") continue;
      try {
        const obj = JSON.parse(data) as {
          choices?: Array<{ delta?: { content?: string } }>;
        };
        const piece = obj.choices?.[0]?.delta?.content;
        if (typeof piece === "string") acc += piece;
      } catch {
        // skip malformed SSE frame
      }
    }
    return acc.trim();
  }
  try {
    const obj = JSON.parse(text) as {
      choices?: Array<{ message?: { content?: ChatMessage["content"] } }>;
    };
    const content = obj.choices?.[0]?.message?.content;
    if (content !== undefined) return messageText(content).trim();
  } catch {
    // not JSON
  }
  return "";
}

// --- daemon calls (recall + capture) -------------------------------

function daemonHeaders(secret: <REDACTED> | undefined): Record<string, string> {
  const h: Record<string, string> = { "content-type": "application/json" };
  if (secret) h["authorization"] = `Bearer ${secret}`;
  return h;
}

async function fetchMemory(ctx: Ctx, query: string): Promise<string> {
  const res = await fetch(`${ctx.daemonUrl}/memwarden/search`, {
    method: "POST",
    headers: daemonHeaders(ctx.secret),
    body: JSON.stringify({
      query,
      format: "narrative",
      project: ctx.project,
      cwd: ctx.cwd,
      safe_only: true, // Verified Recall: never inject stale memory into a model call
      ...(ctx.tokenBudget ? { token_budget: <REDACTED> } : {}),
    }),
  });
  if (!res.ok) return "";
  const body = (await res.json()) as { text?: string };
  return typeof body.text === "string" ? body.text : "";
}

async function captureExchange(
  ctx: Ctx,
  query: string,
  answer: string,
): Promise<void> {
  await fetch(`${ctx.daemonUrl}/memwarden/observe`, {
    method: "POST",
    headers: daemonHeaders(ctx.secret),
    body: JSON.stringify({
      hookType: "post_tool_use",
      sessionId: ctx.sessionId,
      project: ctx.project,
      cwd: ctx.cwd,
      timestamp: new Date().toISOString(),
      data: {
        tool_name: "chat",
        tool_input: { prompt: query.slice(0, 4000) },
        tool_output: answer.slice(0, 8000),
      },
    }),
  }).catch(() => undefined);
}

//
// The single source of truth for KV scope names, plus a few pure id and
// similarity helpers. Scopes are exact-match strings (no prefix hierarchy):
// list(scope) returns just that scope's values, and cross-session enumeration
// is list(KV.sessions) followed by list(KV.observations(id)) per session.

import { createHash, randomUUID } from "node:crypto";

